    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            LexErrorKind::Unexpected(b) => write!(f, "unexpected '{}'.", *b as char),
            LexErrorKind::UnexpectedEof => write!(f, "unexpected end of file."),
