#[derive(Debug, Clone, PartialEq)]
pub struct Token {
    pub kind: TokenKind,
    pub pos: Pos,
}

#[derive(Debug, Clone, PartialEq)]
pub enum LexErrorKind {
    Unexpected(u8),
    UnexpectedEof,
    InvalidEscape(Vec<u8>),
    EmptyCharLiteral,
    InvalidNumber(Vec<u8>),
    InvalidIdentifier(Vec<u8>),
}

#[derive(Debug, Clone, PartialEq)]
pub struct LexError {
    pub kind: LexErrorKind,
    pub pos: Pos,
}

impl fmt::Display for LexErrorKind {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            LexErrorKind::Unexpected(b) => write!(f, "unexpected '{}'.", *b as char),
            LexErrorKind::UnexpectedEof => write!(f, "unexpected end of file."),
            LexErrorKind::InvalidEscape(s) => {
                write!(f, "invalid escape sequence '\\{}'.", String::from_utf8_lossy(s))
            }
            LexErrorKind::EmptyCharLiteral => write!(f, "empty char literal."),
            LexErrorKind::InvalidNumber(s) => {
                write!(f, "invalid number '{}'.", String::from_utf8_lossy(s))
            }
            LexErrorKind::InvalidIdentifier(s) => {
                write!(f, "invalid identifier '{}'.", String::from_utf8_lossy(s))
            }
        }
    }
}

pub type LexItem = Result<Token, LexError>;

/// Panic reproduction for unimplemented expansions in the original lexer.
pub fn unimplemented_expansion(line: u32) -> ! {
    eprintln!(
        "\nthread 'main' panicked at src/syntax/lexer/automata/expansion.rs:{}:17:\nnot yet implemented\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace",
        line
    );
    std::process::exit(101);
}

fn is_ident_start(b: u8) -> bool {
    b.is_ascii_alphabetic() || b == b'_'
}

fn is_ident_char(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_'
}

fn is_valid_identifier(s: &[u8]) -> bool {
    match s.first() {
        Some(&b) if is_ident_start(b) => s[1..].iter().all(|&c| is_ident_char(c)),
        _ => false,
    }
}

fn keyword(s: &[u8]) -> Option<TokenKind> {
    use TokenKind::*;
    Some(match s {
        b"let" => Let,
        b"if" => If,
        b"then" => Then,
        b"else" => Else,
        b"end" => End,
        b"for" => For,
        b"in" => In,
        b"do" => Do,
        b"while" => While,
        b"function" => Function,
        b"return" => Return,
        b"break" => Break,
        b"self" => SelfKw,
        b"not" => Not,
        b"and" => And,
        b"or" => Or,
        b"true" => True,
        b"false" => False,
        b"nil" => Nil,
        _ => return None,
    })
}

/// Escape handling for regular string/char literals.
fn literal_escape(b: u8) -> Option<u8> {
    match b {
        b'n' => Some(b'\n'),
        b't' => Some(b'\t'),
        b'0' => Some(0),
        b'\\' => Some(b'\\'),
        b'"' => Some(b'"'),
        b'\'' => Some(b'\''),
        _ => None,
    }
}

/// Escape handling inside single quotes of command arguments.
fn squote_escape(b: u8) -> Option<u8> {
    match b {
        b'n' => Some(b'\n'),
        b't' => Some(b'\t'),
        b'0' => Some(0),
        b'\\' => Some(b'\\'),
        b'\'' => Some(b'\''),
        _ => None,
    }
}

/// Escape handling inside double quotes of command arguments.
fn dquote_escape(b: u8) -> Option<u8> {
    match b {
        b'n' => Some(b'\n'),
        b't' => Some(b'\t'),
        b'0' => Some(0),
        b'\\' => Some(b'\\'),
        b'"' => Some(b'"'),
        b'$' => Some(b'$'),
        _ => None,
    }
}

/// Escape handling in unquoted command arguments.
fn word_escape(b: u8) -> Option<u8> {
    match b {
        b'n' => Some(b'\n'),
        b't' => Some(b'\t'),
        b'0' => Some(0),
        b'\\' => Some(b'\\'),
        b'"' => Some(b'"'),
        b'\'' => Some(b'\''),
        b'$' => Some(b'$'),
        b'#' => Some(b'#'),
        b';' => Some(b';'),
        b'<' => Some(b'<'),
        b'>' => Some(b'>'),
        b'=' => Some(b'='),
        b'?' => Some(b'?'),
        b' ' => Some(b' '),
        _ => None,
    }
}

fn is_word_terminator(b: u8) -> bool {
    b.is_ascii_whitespace() || matches!(b, b';' | b'}' | b'>' | b'<' | b'?' | b'#')
}

pub struct Lexer<'a> {
    src: &'a [u8],
    offset: usize,
    line: u32,
    column: u32,
    command_mode: bool,
    queue: VecDeque<LexItem>,
    finished: bool,
}

impl<'a> Lexer<'a> {
    pub fn new(src: &'a [u8]) -> Self {
        Lexer {
            src,
            offset: 0,
            line: 1,
            column: 0,
            command_mode: false,
            queue: VecDeque::new(),
            finished: false,
        }
    }

    fn pos(&self) -> Pos {
        Pos { line: self.line, column: self.column }
    }

    fn peek(&self) -> Option<u8> {
        self.src.get(self.offset).copied()
    }

    fn peek_at(&self, n: usize) -> Option<u8> {
        self.src.get(self.offset + n).copied()
    }

    fn advance(&mut self) -> Option<u8> {
        let b = self.src.get(self.offset).copied()?;
        self.offset += 1;
        if b == b'\n' {
            self.line += 1;
            self.column = 0;
        } else {
            self.column += 1;
        }
        Some(b)
    }

    fn emit(&mut self, kind: TokenKind, pos: Pos) {
        self.queue.push_back(Ok(Token { kind, pos }));
    }

    fn error(&mut self, kind: LexErrorKind, pos: Pos) {
        self.queue.push_back(Err(LexError { kind, pos }));
    }

    pub fn next_item(&mut self) -> Option<LexItem> {
        loop {
            if let Some(item) = self.queue.pop_front() {
                return Some(item);
            }
            if self.finished {
                return None;
            }
            if self.command_mode {
                self.lex_command();
            } else {
                self.lex_normal();
            }
        }
    }

    // ---------------------------------------------------------------- normal mode

    fn lex_normal(&mut self) {
        let b = match self.peek() {
            Some(b) => b,
            None => {
                self.finished = true;
                return;
            }
        };
        let pos = self.pos();
        if b.is_ascii_whitespace() {
            self.advance();
            return;
        }
        match b {
            b'#' => {
                while let Some(c) = self.peek() {
                    if c == b'\n' {
                        break;
                    }
                    self.advance();
                }
            }
            b'"' => self.lex_string(),
            b'\'' => self.lex_char(),
            _ if is_ident_start(b) => {
                let start = self.offset;
                while let Some(c) = self.peek() {
                    if is_ident_char(c) {
                        self.advance();
                    } else {
                        break;
                    }
                }
                let text = &self.src[start..self.offset];
                let kind = keyword(text)
                    .unwrap_or_else(|| TokenKind::Identifier(Rc::from(String::from_utf8_lossy(text).as_ref())));
                self.emit(kind, pos);
            }
            _ if b.is_ascii_digit() => self.lex_number(),
            _ => self.lex_symbol(),
        }
    }

    fn lex_symbol(&mut self) {
        use TokenKind::*;
        let pos = self.pos();
        let b = self.advance().unwrap();
        let next = self.peek();
        let two = |this: &mut Self, kind: TokenKind| {
            this.advance();
            this.emit(kind, pos);
        };
        match b {
            b'+' if next == Some(b'+') => two(self, Concat),
            b'+' => self.emit(Plus, pos),
            b'-' => self.emit(Minus, pos),
            b'*' => self.emit(Star, pos),
            b'/' => self.emit(Slash, pos),
            b'%' => self.emit(Percent, pos),
            b'=' if next == Some(b'=') => two(self, EqEq),
            b'=' => self.emit(Assign, pos),
            b'!' if next == Some(b'=') => two(self, NotEq),
            b'<' if next == Some(b'=') => two(self, Le),
            b'<' => self.emit(Lt, pos),
            b'>' if next == Some(b'=') => two(self, Ge),
            b'>' => self.emit(Gt, pos),
            b'.' => self.emit(Dot, pos),
            b',' => self.emit(Comma, pos),
            b':' => self.emit(Colon, pos),
            b'(' => self.emit(OpenParen, pos),
            b')' => self.emit(CloseParen, pos),
            b'[' => self.emit(OpenBracket, pos),
            b']' => self.emit(CloseBracket, pos),
            b'@' if next == Some(b'[') => two(self, OpenDict),
            b'{' => {
                self.command_mode = true;
                self.emit(OpenCommand, pos);
            }
            b'$' if next == Some(b'{') => {
                self.advance();
                self.command_mode = true;
                self.emit(OpenCapture, pos);
            }
            b'&' if next == Some(b'{') => {
                self.advance();
                self.command_mode = true;
                self.emit(OpenAsync, pos);
            }
            _ => self.error(LexErrorKind::Unexpected(b), pos),
        }
    }

    fn lex_string(&mut self) {
        let pos = self.pos();
        self.advance(); // opening quote
        let mut buf = Vec::new();
        loop {
            match self.peek() {
                None => {
                    let eof = self.pos();
                    self.error(LexErrorKind::UnexpectedEof, eof);
                    self.finished = true;
                    return;
                }
                Some(b'"') => {
                    self.advance();
                    self.emit(TokenKind::Str(buf), pos);
                    return;
                }
                Some(b'\\') => {
                    let esc_pos = self.pos();
                    self.advance();
                    match self.peek() {
                        None => {
                            // treat as EOF
                            let eof = self.pos();
                            self.error(LexErrorKind::UnexpectedEof, eof);
                            self.finished = true;
                            return;
                        }
                        Some(c) => {
                            self.advance();
                            match literal_escape(c) {
                                Some(v) => buf.push(v),
                                None => self.error(LexErrorKind::InvalidEscape(vec![c]), esc_pos),
                            }
                        }
                    }
                }
                Some(c) => {
                    self.advance();
                    buf.push(c);
                }
            }
        }
    }

    fn lex_char(&mut self) {
        let pos = self.pos();
        self.advance(); // opening quote
        let mut value: u8 = 0;
        // read the character
        match self.peek() {
            None => {
                let eof = self.pos();
                self.error(LexErrorKind::UnexpectedEof, eof);
                self.finished = true;
                return;
            }
            Some(b'\'') => {
                self.advance();
                self.error(LexErrorKind::EmptyCharLiteral, pos);
                return;
            }
            Some(b'\\') => {
                let esc_pos = self.pos();
                self.advance();
                match self.peek() {
                    None => {
                        let eof = self.pos();
                        self.error(LexErrorKind::UnexpectedEof, eof);
                        self.finished = true;
                        return;
                    }
                    Some(c) => {
                        self.advance();
                        match literal_escape(c) {
                            Some(v) => value = v,
                            None => self.error(LexErrorKind::InvalidEscape(vec![c]), esc_pos),
                        }
                    }
                }
            }
            Some(c) => {
                self.advance();
                value = c;
            }
        }
        // expect closing quote
        loop {
            match self.peek() {
                None => {
                    let eof = self.pos();
                    self.error(LexErrorKind::UnexpectedEof, eof);
                    self.finished = true;
                    return;
                }
                Some(b'\'') => {
                    self.advance();
                    self.emit(TokenKind::Byte(value), pos);
                    return;
                }
                Some(c) => {
                    let p = self.pos();
                    self.advance();
                    self.error(LexErrorKind::Unexpected(c), p);
                }
            }
        }
    }

    fn lex_number(&mut self) {
        let pos = self.pos();
        let start = self.offset;
        // integer part
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                self.advance();
            } else {
                break;
            }
        }
        let mut is_float = false;
        match self.peek() {
            Some(b'.') => {
                self.advance();
                is_float = true;
                // must have digit
                match self.peek() {
                    Some(c) if c.is_ascii_digit() => {
                        while let Some(c) = self.peek() {
                            if c.is_ascii_digit() {
                                self.advance();
                            } else {
                                break;
                            }
                        }
                    }
                    Some(c) => {
                        self.advance();
                        self.error(LexErrorKind::Unexpected(c), pos);
                        return;
                    }
                    None => {
                        self.error(LexErrorKind::UnexpectedEof, self.pos());
                        self.finished = true;
                        return;
                    }
                }
            }
            _ => {}
        }
        if let Some(b'e') | Some(b'E') = self.peek() {
            self.advance();
            is_float = true;
            match self.peek() {
                Some(c) if c.is_ascii_digit() => {
                    while let Some(c) = self.peek() {
                        if c.is_ascii_digit() {
                            self.advance();
                        } else {
                            break;
                        }
                    }
                }
                Some(c) => {
                    self.advance();
                    self.error(LexErrorKind::Unexpected(c), pos);
                    return;
                }
                None => {
                    self.error(LexErrorKind::UnexpectedEof, self.pos());
                    self.finished = true;
                    return;
                }
            }
        }
        let text = &self.src[start..self.offset];
        let text_str = std::str::from_utf8(text).unwrap();
        if is_float {
            let v: f64 = text_str.parse().unwrap_or(f64::INFINITY);
            self.emit(TokenKind::Float(v), pos);
        } else {
            match text_str.parse::<i64>() {
                Ok(v) => self.emit(TokenKind::Int(v), pos),
                Err(_) => {
                    let t = text.to_vec();
                    // the terminating character is swallowed
                    self.advance();
                    self.error(LexErrorKind::InvalidNumber(t), pos);
                }
            }
        }
    }

    // ---------------------------------------------------------------- command mode

    fn lex_command(&mut self) {
        use TokenKind::*;
        let b = match self.peek() {
            Some(b) => b,
            None => {
                let eof = self.pos();
                self.error(LexErrorKind::UnexpectedEof, eof);
                self.finished = true;
                return;
            }
        };
        let pos = self.pos();
        if b.is_ascii_whitespace() {
            self.advance();
            return;
        }
        match b {
            b'#' => {
                while let Some(c) = self.peek() {
                    if c == b'\n' {
                        break;
                    }
                    self.advance();
                }
            }
            b'}' => {
                self.advance();
                self.command_mode = false;
                self.emit(CloseCommand, pos);
            }
            b';' => {
                self.advance();
                self.emit(Semicolon, pos);
            }
            b'|' => {
                self.advance();
                self.emit(Pipe, pos);
            }
            b'?' => {
                self.advance();
                self.emit(Try, pos);
            }
            b'>' => {
                self.advance();
                if self.peek() == Some(b'>') {
                    self.advance();
                    self.emit(Append, pos);
                } else {
                    self.emit(Output, pos);
                }
            }
            b'<' => {
                self.advance();
                if self.peek() == Some(b'<') {
                    self.advance();
                    self.emit(HereString, pos);
                } else {
                    self.emit(Input, pos);
                }
            }
            _ => self.lex_argument(),
        }
    }

    /// Lex a command argument. Reproduces the quirks of the original automaton.
    fn lex_argument(&mut self) {
        let pos = self.pos();
        let mut units: Vec<ArgUnit> = Vec::new();
        let mut word: Vec<u8> = Vec::new();
        let mut first = true;

        macro_rules! flush_word {
            () => {
                if !word.is_empty() {
                    units.push(ArgUnit::Literal(std::mem::take(&mut word)));
                }
            };
        }

        loop {
            let c = match self.peek() {
                Some(c) => c,
                None => {
                    // EOF handling
                    if !word.is_empty() {
                        // in-progress literal: dropped silently
                        self.finished = true;
                        return;
                    }
                    self.emit(TokenKind::Argument(units), pos);
                    let eof = self.pos();
                    self.error(LexErrorKind::UnexpectedEof, eof);
                    self.finished = true;
                    return;
                }
            };
            if is_word_terminator(c) {
                flush_word!();
                self.emit(TokenKind::Argument(units), pos);
                return;
            }
            match c {
                b'"' => {
                    flush_word!();
                    self.advance();
                    match self.lex_dquote() {
                        Some(u) => units.push(ArgUnit::DoubleQuoted(u)),
                        None => {
                            // EOF inside quotes with pending literal: dropped
                            self.finished = true;
                            return;
                        }
                    }
                    if self.finished {
                        // EOF right after quote state with empty buffer: error, emit, root error
                        self.emit(TokenKind::Argument(units), pos);
                        let eof = self.pos();
                        self.error(LexErrorKind::UnexpectedEof, eof);
                        return;
                    }
                }
                b'\'' => {
                    flush_word!();
                    self.advance();
                    match self.lex_squote() {
                        Some(s) => units.push(ArgUnit::SingleQuoted(s)),
                        None => {
                            self.finished = true;
                            return;
                        }
                    }
                    if self.finished {
                        self.emit(TokenKind::Argument(units), pos);
                        let eof = self.pos();
                        self.error(LexErrorKind::UnexpectedEof, eof);
                        return;
                    }
                }
                b'$' => {
                    flush_word!();
                    match self.lex_dollar() {
                        DollarResult::Ok(id) => units.push(ArgUnit::Dollar(id)),
                        DollarResult::Invalid => {}
                        DollarResult::Dropped => {
                            self.finished = true;
                            return;
                        }
                    }
                    if self.finished {
                        self.emit(TokenKind::Argument(units), pos);
                        let eof = self.pos();
                        self.error(LexErrorKind::UnexpectedEof, eof);
                        return;
                    }
                }
                b'*' => {
                    flush_word!();
                    self.advance();
                    units.push(ArgUnit::Star);
                }
                b'%' => {
                    flush_word!();
                    self.advance();
                    units.push(ArgUnit::Percent);
                }
                b'~' if first => {
                    self.advance();
                    match self.peek() {
                        Some(b'/') => {
                            self.advance();
                            units.push(ArgUnit::Home);
                        }
                        Some(_) => {
                            word.push(b'~');
                        }
                        None => {
                            self.finished = true;
                            return;
                        }
                    }
                }
                b'\\' => {
                    match self.lex_escape(word_escape) {
                        Some(v) => word.push(v),
                        None => {
                            self.finished = true;
                            return;
                        }
                    }
                }
                b'[' => unimplemented_expansion(87),
                b'{' => unimplemented_expansion(91),
                _ => {
                    self.advance();
                    word.push(c);
                }
            }
            first = false;
        }
    }

    /// Handles a backslash escape with the original's quirky error recovery.
    /// Returns None on EOF.
    fn lex_escape(&mut self, valid: fn(u8) -> Option<u8>) -> Option<u8> {
        let esc_pos = self.pos();
        self.advance(); // backslash
        let mut buf: Vec<u8> = Vec::new();
        loop {
            let c = self.peek()?;
            self.advance();
            match valid(c) {
                Some(v) => return Some(v),
                None => {
                    buf.push(c);
                    self.error(LexErrorKind::InvalidEscape(buf.clone()), esc_pos);
                }
            }
        }
    }

    /// Lex the inside of double quotes (opening quote already consumed).
    /// Returns None if EOF was reached with a pending literal (dropped).
    /// Sets `finished` when EOF reached with an empty buffer (error reported).
    fn lex_dquote(&mut self) -> Option<Vec<DqUnit>> {
        let mut units: Vec<DqUnit> = Vec::new();
        let mut buf: Vec<u8> = Vec::new();
        loop {
            let c = match self.peek() {
                Some(c) => c,
                None => {
                    if !buf.is_empty() {
                        return None;
                    }
                    let eof = self.pos();
                    self.error(LexErrorKind::UnexpectedEof, eof);
                    self.finished = true;
                    return Some(units);
                }
            };
            match c {
                b'"' => {
                    self.advance();
                    if !buf.is_empty() {
                        units.push(DqUnit::Literal(buf));
                    }
                    return Some(units);
                }
                b'\\' => match self.lex_escape(dquote_escape) {
                    Some(v) => buf.push(v),
                    None => return None,
                },
                b'$' => {
                    if !buf.is_empty() {
                        units.push(DqUnit::Literal(std::mem::take(&mut buf)));
                    }
                    match self.lex_dollar() {
                        DollarResult::Ok(id) => units.push(DqUnit::Dollar(id)),
                        DollarResult::Invalid => {}
                        DollarResult::Dropped => return None,
                    }
                    if self.finished {
                        // EOF after dollar: dquote state with empty buffer reports EOF
                        let eof = self.pos();
                        self.error(LexErrorKind::UnexpectedEof, eof);
                        return Some(units);
                    }
                }
                _ => {
                    self.advance();
                    buf.push(c);
                }
            }
        }
    }

    fn lex_squote(&mut self) -> Option<Vec<u8>> {
        let mut buf: Vec<u8> = Vec::new();
        loop {
            let c = match self.peek() {
                Some(c) => c,
                None => {
                    if !buf.is_empty() {
                        return None;
                    }
                    let eof = self.pos();
                    self.error(LexErrorKind::UnexpectedEof, eof);
                    self.finished = true;
                    return Some(buf);
                }
            };
            match c {
                b'\'' => {
                    self.advance();
                    return Some(buf);
                }
                b'\\' => match self.lex_escape(squote_escape) {
                    Some(v) => buf.push(v),
                    None => return None,
                },
                _ => {
                    self.advance();
                    buf.push(c);
                }
            }
        }
    }

    /// Lex a `$` expansion (the `$` not yet consumed).
    fn lex_dollar(&mut self) -> DollarResult {
        let dollar_pos = self.pos();
        self.advance(); // $
        match self.peek() {
            None => {
                self.error(LexErrorKind::InvalidIdentifier(Vec::new()), dollar_pos);
                self.finished = true;
                DollarResult::Invalid
            }
            Some(b'{') => {
                self.advance();
                let mut buf = Vec::new();
                loop {
                    match self.peek() {
                        None => {
                            let eof = self.pos();
                            self.error(LexErrorKind::UnexpectedEof, eof);
                            self.finished = true;
                            return DollarResult::Invalid;
                        }
                        Some(b'}') => {
                            self.advance();
                            break;
                        }
                        Some(c) => {
                            self.advance();
                            buf.push(c);
                        }
                    }
                }
                if is_valid_identifier(&buf) {
                    DollarResult::Ok(Rc::from(String::from_utf8_lossy(&buf).as_ref()))
                } else {
                    self.error(LexErrorKind::InvalidIdentifier(buf), dollar_pos);
                    DollarResult::Invalid
                }
            }
            Some(c) => {
                // first char consumed unconditionally
                self.advance();
                let mut buf = vec![c];
                loop {
                    match self.peek() {
                        None => {
                            if is_valid_identifier(&buf) {
                                return DollarResult::Dropped;
                            }
                            self.error(LexErrorKind::InvalidIdentifier(buf), dollar_pos);
                            self.finished = true;
                            return DollarResult::Invalid;
                        }
                        Some(c) if is_ident_char(c) => {
                            self.advance();
                            buf.push(c);
                        }
                        Some(_) => {
                            if is_valid_identifier(&buf) {
                                return DollarResult::Ok(Rc::from(String::from_utf8_lossy(&buf).as_ref()));
                            }
                            // swallow the terminating character
                            self.advance();
                            self.error(LexErrorKind::InvalidIdentifier(buf), dollar_pos);
                            return DollarResult::Invalid;
                        }
                    }
                }
            }
        }
    }
}

enum DollarResult {
    Ok(Rc<str>),
    Invalid,
    Dropped,
}
