    Or,
    Concat,
}

impl fmt::Display for UnaryOp {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            UnaryOp::Minus => write!(f, "-"),
            UnaryOp::Not => write!(f, "not"),
        }
    }
}

impl fmt::Display for BinaryOp {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        let s = match self {
            BinaryOp::Plus => "+",
            BinaryOp::Minus => "-",
            BinaryOp::Times => "*",
            BinaryOp::Div => "/",
            BinaryOp::Mod => "%",
            BinaryOp::Equals => "==",
            BinaryOp::NotEquals => "!=",
            BinaryOp::Greater => ">",
            BinaryOp::GreaterEquals => ">=",
            BinaryOp::Lower => "<",
            BinaryOp::LowerEquals => "<=",
            BinaryOp::And => "and",
            BinaryOp::Or => "or",
            BinaryOp::Concat => "++",
        };
        write!(f, "{}", s)
    }
}

#[derive(Debug, Clone)]
pub struct Block(pub Vec<Statement>);

#[derive(Debug, Clone)]
pub enum Literal {
    Nil,
    True,
    False,
    Int(i64),
    Float(f64),
    Byte(u8),
    String(Vec<u8>),
    Array(Vec<Expr>),
    Dict(Vec<(DictKey, Expr)>),
    Function { params: Vec<Param>, body: Block },
    /// Identifier used as a dict field name (in access expressions).
    Identifier(Symbol),
}

#[derive(Debug, Clone)]
pub enum DictKey {
    Ident(Symbol, Pos),
    IllFormed,
}

#[derive(Debug, Clone)]
pub enum Param {
    Ident(Symbol, Pos),
    IllFormed,
}

#[derive(Debug, Clone)]
pub enum Expr {
    SelfKw { pos: Pos },
    Identifier { name: Symbol, pos: Pos },
    Literal { lit: Literal, pos: Pos },
    Unary { op: UnaryOp, operand: Box<Expr>, pos: Pos },
    Binary { op: BinaryOp, left: Box<Expr>, right: Box<Expr>, pos: Pos },
    If { condition: Box<Expr>, then: Block, otherwise: Block, pos: Pos },
    Access { object: Box<Expr>, field: Box<Expr>, pos: Pos },
    Call { function: Box<Expr>, args: Vec<Expr>, pos: Pos },
    CommandBlock { kind: CommandBlockKind, commands: Vec<Command>, pos: Pos },
    IllFormed,
}

impl Expr {
    pub fn pos(&self) -> Pos {
        match self {
            Expr::SelfKw { pos }
            | Expr::Identifier { pos, .. }
            | Expr::Literal { pos, .. }
            | Expr::Unary { pos, .. }
            | Expr::Binary { pos, .. }
            | Expr::If { pos, .. }
            | Expr::Access { pos, .. }
            | Expr::Call { pos, .. }
            | Expr::CommandBlock { pos, .. } => *pos,
            Expr::IllFormed => Pos::default(),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CommandBlockKind {
    Synchronous,
    Asynchronous,
    Capture,
}

#[derive(Debug, Clone)]
pub enum ArgPart {
