    IllFormed,
}

#[derive(Debug, Clone)]
pub enum Statement {
    Let { name: Option<Symbol>, name_pos: Pos, init: Expr, pos: Pos },
    Assign { left: Expr, right: Expr, pos: Pos },
    Return { expr: Expr, pos: Pos },
    Break { pos: Pos },
    While { condition: Expr, block: Block, pos: Pos },
    For { name: Option<Symbol>, name_pos: Pos, expr: Expr, block: Block, pos: Pos },
    Expr(Expr),
    IllFormed,
}

pub const ILL_FORMED: &str = "***ill-formed***";

// ------------------------------------------------------------------ printing

fn tabs(n: usize) -> String {
    "\t".repeat(n)
}

pub trait AstDisplay {
    fn fmt_ast(&self, out: &mut String, indent: usize, pretty: bool);
}

pub fn ast_to_string(node: &impl AstDisplay, indent: usize, pretty: bool) -> String {
    let mut s = String::new();
    node.fmt_ast(&mut s, indent, pretty);
    s
}

/// Block printing style used by if/while/for.
pub fn fmt_block_stmts<T: AstDisplay>(stmts: &[T], out: &mut String, indent: usize, pretty: bool) {
    if pretty {
        for s in stmts {
            out.push_str(&tabs(indent + 1));
            s.fmt_ast(out, indent + 1, pretty);
            out.push('\n');
        }
    } else if !stmts.is_empty() {
        out.push(' ');
        let mut first = true;
        for s in stmts {
            if !first {
                out.push_str("; ");
            }
            first = false;
            s.fmt_ast(out, indent, pretty);
        }
        out.push(' ');
    }
}

/// Block printing style used by functions.
pub fn fmt_fn_block<T: AstDisplay>(stmts: &[T], out: &mut String, indent: usize, pretty: bool) {
    if pretty {
        out.push('\n');
        let mut first = true;
        for s in stmts {
            if !first {
                out.push('\n');
            }
            first = false;
            out.push_str(&tabs(indent + 1));
            s.fmt_ast(out, indent + 1, pretty);
        }
        out.push('\n');
    } else {
        out.push(' ');
        let mut first = true;
        for s in stmts {
            if !first {
                out.push_str("; ");
            }
            first = false;
            s.fmt_ast(out, indent, pretty);
        }
        if !stmts.is_empty() {
            out.push(' ');
        }
    }
}

pub fn fmt_literal_scalar(lit: &Literal, out: &mut String) -> bool {
    match lit {
        Literal::Nil => out.push_str("nil"),
        Literal::True => out.push_str("true"),
        Literal::False => out.push_str("false"),
        Literal::Int(i) => write!(out, "{}", i).unwrap(),
        Literal::Float(x) => write!(out, "{}", x).unwrap(),
        Literal::Byte(b) => write!(out, "'{}'", escape_debug_byte(*b)).unwrap(),
        Literal::String(s) => write!(out, "\"{}\"", escape_debug_bytes(s)).unwrap(),
        Literal::Identifier(id) => out.push_str(id),
        _ => return false,
    }
    true
}

/// Generic formatting of array/dict/function literals, parameterized over the
/// element printer so it can be shared with the program printer.
pub fn fmt_array<T: AstDisplay>(items: &[T], out: &mut String, indent: usize, pretty: bool) {
    if items.is_empty() {
        out.push_str("[]");
        return;
    }
    if pretty {
        out.push_str("[\n");
        let mut first = true;
        for item in items {
            if !first {
                out.push_str(",\n");
            }
            first = false;
            out.push_str(&tabs(indent + 1));
            item.fmt_ast(out, indent + 1, pretty);
        }
        out.push('\n');
        out.push_str(&tabs(indent));
        out.push(']');
    } else {
        out.push_str("[ ");
        let mut first = true;
        for item in items {
            if !first {
                out.push_str(", ");
            }
            first = false;
            item.fmt_ast(out, indent, pretty);
        }
        out.push_str(" ]");
    }
}

pub fn fmt_dict<T: AstDisplay>(items: &[(String, T)], out: &mut String, indent: usize, pretty: bool) {
    if items.is_empty() {
        out.push_str("@[]");
        return;
    }
    if pretty {
        out.push_str("@[\n");
        let mut first = true;
        for (k, v) in items {
            if !first {
                out.push_str(",\n");
            }
            first = false;
            out.push_str(&tabs(indent + 1));
            out.push_str(k);
            out.push_str(": ");
            v.fmt_ast(out, indent + 1, pretty);
        }
        out.push('\n');
        out.push_str(&tabs(indent));
        out.push(']');
    } else {
        out.push_str("@[ ");
        let mut first = true;
        for (k, v) in items {
            if !first {
                out.push_str(", ");
            }
            first = false;
            out.push_str(k);
            out.push_str(": ");
            v.fmt_ast(out, indent, pretty);
        }
        out.push_str(" ]");
    }
}

pub fn fmt_if<C: AstDisplay, S: AstDisplay>(
    cond: &C,
    then: &[S],
    otherwise: &[S],
    out: &mut String,
    indent: usize,
    pretty: bool,
) {
    out.push_str("if ");
    cond.fmt_ast(out, indent, false);
    out.push_str(" then");
    if pretty {
        out.push('\n');
    }
    fmt_block_stmts(then, out, indent, pretty);
    if !otherwise.is_empty() {
        if pretty {
            out.push_str(&tabs(indent));
            out.push_str("else\n");
        } else {
            out.push_str("else");
        }
        fmt_block_stmts(otherwise, out, indent, pretty);
    }
    if pretty {
        out.push_str(&tabs(indent));
    }
    out.push_str("end");
}

impl AstDisplay for DictKey {
    fn fmt_ast(&self, out: &mut String, _indent: usize, _pretty: bool) {
        match self {
            DictKey::Ident(s, _) => out.push_str(s),
            DictKey::IllFormed => out.push_str(ILL_FORMED),
        }
    }
}

impl AstDisplay for Expr {
    fn fmt_ast(&self, out: &mut String, indent: usize, pretty: bool) {
        match self {
            Expr::SelfKw { .. } => out.push_str("self"),
            Expr::Identifier { name, .. } => out.push_str(name),
            Expr::Literal { lit, .. } => match lit {
                Literal::Array(items) => fmt_array(items, out, indent, pretty),
                Literal::Dict(items) => {
                    let items: Vec<(String, &Expr)> =
                        items.iter().map(|(k, v)| (ast_to_string(k, 0, false), v)).collect();
                    fmt_dict(&items, out, indent, pretty);
                }
                Literal::Function { params, body } => {
                    out.push_str("function(");
                    let mut first = true;
                    for p in params {
                        if !first {
                            out.push_str(", ");
                        }
                        first = false;
                        match p {
                            Param::Ident(s, _) => out.push_str(s),
                            Param::IllFormed => out.push_str(ILL_FORMED),
                        }
                    }
                    out.push(')');
                    fmt_fn_block(&body.0, out, indent, pretty);
                    if pretty {
                        out.push_str(&tabs(indent));
                    }
                    out.push_str("end");
                }
                other => {
                    fmt_literal_scalar(other, out);
                }
            },
            Expr::Unary { op, operand, .. } => {
                out.push('(');
                write!(out, "{} ", op).unwrap();
                operand.fmt_ast(out, indent, false);
                out.push(')');
            }
            Expr::Binary { op, left, right, .. } => {
                out.push('(');
                left.fmt_ast(out, indent, false);
                write!(out, " {} ", op).unwrap();
                right.fmt_ast(out, indent, false);
                out.push(')');
            }
            Expr::If { condition, then, otherwise, .. } => {
                fmt_if(condition.as_ref(), &then.0, &otherwise.0, out, indent, pretty);
            }
            Expr::Access { object, field, .. } => {
                object.fmt_ast(out, indent, false);
                match field.as_ref() {
                    Expr::Literal { lit: Literal::Identifier(id), .. } => {
                        out.push('.');
                        out.push_str(id);
                    }
                    other => {
                        out.push('[');
                        other.fmt_ast(out, indent, false);
                        out.push(']');
                    }
                }
            }
            Expr::Call { function, args, .. } => {
                function.fmt_ast(out, indent, false);
                out.push('(');
                let mut first = true;
                for a in args {
                    if !first {
                        out.push_str(", ");
                    }
                    first = false;
                    a.fmt_ast(out, indent, false);
                }
                out.push(')');
            }
            Expr::CommandBlock { kind, commands, .. } => {
                fmt_command_block(*kind, commands, out, indent, pretty);
            }
            Expr::IllFormed => out.push_str(ILL_FORMED),
        }
    }
}

pub fn fmt_command_block<C: AstDisplay>(
    kind: CommandBlockKind,
    commands: &[C],
    out: &mut String,
    indent: usize,
    pretty: bool,
) {
    match kind {
        CommandBlockKind::Synchronous => out.push('{'),
        CommandBlockKind::Asynchronous => out.push_str("&{"),
        CommandBlockKind::Capture => out.push_str("${"),
    }
    if pretty {
        out.push('\n');
        let mut first = true;
        for c in commands {
            if !first {
                out.push_str(";\n");
            }
            first = false;
            out.push_str(&tabs(indent + 1));
            c.fmt_ast(out, indent + 1, pretty);
        }
        out.push('\n');
        out.push_str(&tabs(indent));
        out.push('}');
    } else {
        out.push(' ');
        let mut first = true;
        for c in commands {
            if !first {
                out.push_str("; ");
            }
            first = false;
            c.fmt_ast(out, indent, pretty);
        }
        out.push_str(" }");
    }
}

impl AstDisplay for Command {
    fn fmt_ast(&self, out: &mut String, indent: usize, pretty: bool) {
        match self {
            Command::Pipeline { commands, abort_on_error } => {
                let mut first = true;
                for c in commands {
                    if !first {
                        out.push_str(" | ");
                    }
                    first = false;
                    c.fmt_ast(out, indent, pretty);
                }
                if !abort_on_error {
                    out.push_str(" ?");
                }
            }
            Command::IllFormed => {
                out.push_str(ILL_FORMED);
                out.push_str(" ?");
            }
        }
    }
}

impl AstDisplay for BasicCommand {
    fn fmt_ast(&self, out: &mut String, indent: usize, pretty: bool) {
        match self {
            BasicCommand::Command { program, args, redirections, .. } => {
                program.fmt_ast(out, indent, pretty);
                for a in args {
                    out.push(' ');
                    a.fmt_ast(out, indent, pretty);
                }
                for r in redirections {
                    out.push(' ');
                    r.fmt_ast(out, indent, pretty);
                }
            }
            BasicCommand::IllFormed => out.push_str(ILL_FORMED),
        }
    }
}

impl AstDisplay for Redirection {
    fn fmt_ast(&self, out: &mut String, indent: usize, pretty: bool) {
        match self {
            Redirection::Output { source, target } => {
                write!(out, "{}>", source).unwrap();
                target.fmt_ast(out, indent, pretty);
            }
            Redirection::Append { source, target } => {
                write!(out, "{}>>", source).unwrap();
                target.fmt_ast(out, indent, pretty);
            }
            Redirection::Input { literal, source } => {
                if *literal {
                    out.push_str("<<");
                } else {
                    out.push('<');
                }
                source.fmt_ast(out, indent, pretty);
            }
            Redirection::IllFormed => out.push_str(ILL_FORMED),
        }
    }
}

impl AstDisplay for RedirectionTarget {
    fn fmt_ast(&self, out: &mut String, indent: usize, pretty: bool) {
        match self {
            RedirectionTarget::Fd(fd) => write!(out, "{}", fd).unwrap(),
            RedirectionTarget::File(arg) => arg.fmt_ast(out, indent, pretty),
        }
    }
}

impl AstDisplay for Argument {
    fn fmt_ast(&self, out: &mut String, _indent: usize, _pretty: bool) {
        out.push('"');
        for p in &self.parts {
            match p {
                ArgPart::Literal(s) => out.push_str(&escape_debug_bytes(s)),
                ArgPart::Dollar(id, _) => write!(out, "${{{}}}", id).unwrap(),
                ArgPart::Star => out.push('*'),
                ArgPart::Percent => out.push('%'),
                ArgPart::Home => out.push_str("~/"),
            }
        }
        out.push('"');
    }
}

impl AstDisplay for Statement {
    fn fmt_ast(&self, out: &mut String, indent: usize, pretty: bool) {
        match self {
            Statement::Let { name, init, .. } => {
                out.push_str("let ");
                match name {
                    Some(n) => out.push_str(n),
                    None => out.push_str(ILL_FORMED),
                }
                out.push_str(" = ");
                init.fmt_ast(out, indent, pretty);
            }
            Statement::Assign { left, right, .. } => {
                left.fmt_ast(out, indent, false);
                out.push_str(" = ");
                right.fmt_ast(out, indent, pretty);
            }
            Statement::Return { expr, .. } => {
                out.push_str("return ");
                expr.fmt_ast(out, indent, pretty);
            }
            Statement::Break { .. } => out.push_str("break"),
            Statement::While { condition, block, .. } => {
                out.push_str("while ");
                condition.fmt_ast(out, indent, false);
                out.push_str(" do");
                if pretty {
                    out.push('\n');
                } else {
                    out.push(' ');
                }
                fmt_block_stmts(&block.0, out, indent, pretty);
                if pretty {
                    out.push_str(&tabs(indent));
                }
                out.push_str("end");
            }
            Statement::For { name, expr, block, .. } => {
                out.push_str("for ");
                match name {
                    Some(n) => out.push_str(n),
                    None => out.push_str(ILL_FORMED),
                }
                out.push_str(" in ");
                expr.fmt_ast(out, indent, false);
                out.push_str(" do");
                if pretty {
                    out.push('\n');
                } else {
                    out.push(' ');
                }
                fmt_block_stmts(&block.0, out, indent, pretty);
                if pretty {
                    out.push_str(&tabs(indent));
                }
                out.push_str("end");
            }
            Statement::Expr(e) => e.fmt_ast(out, indent, pretty),
            Statement::IllFormed => out.push_str(ILL_FORMED),
        }
    }
}

pub struct Ast {
    pub statements: Vec<Statement>,
}

impl Ast {
    pub fn to_pretty_string(&self) -> String {
        let mut out = String::new();
        let mut first = true;
        for s in &self.statements {
            if !first {
                out.push('\n');
            }
            first = false;
            s.fmt_ast(&mut out, 0, true);
        }
        out
    }
}
