use std::fmt;

use crate::ast::*;
use crate::lexer::{ArgUnit, DqUnit, LexError, Lexer, Token, TokenKind};
use crate::pos::Pos;

#[derive(Debug, Clone)]
pub enum SyntaxError {
    Lex(LexError),
    Unexpected { token: String, pos: Pos, expected: String },
    UnexpectedEof,
    EmptyCommandBlock { pos: Pos },
}

impl SyntaxError {
    pub fn pos(&self) -> Option<Pos> {
        match self {
            SyntaxError::Lex(e) => Some(e.pos),
            SyntaxError::Unexpected { pos, .. } => Some(*pos),
            SyntaxError::UnexpectedEof => None,
            SyntaxError::EmptyCommandBlock { pos } => Some(*pos),
        }
    }

    pub fn message(&self) -> String {
        match self {
            SyntaxError::Lex(e) => e.kind.to_string(),
            SyntaxError::Unexpected { token, expected, .. } => {
                format!("unexpected '{}', expected {}", token, expected)
            }
            SyntaxError::UnexpectedEof => "unexpected end of file".to_string(),
            SyntaxError::EmptyCommandBlock { .. } => "empty command block".to_string(),
        }
    }

    pub fn display(&self, path: &str) -> String {
        match self.pos() {
            Some(pos) => format!("Error: {} ({}) - {}", path, pos, self.message()),
            None => format!("Error: {}", self.message()),
        }
    }
}

impl fmt::Display for SyntaxError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{}", self.message())
    }
}

type PResult<T> = Result<T, SyntaxError>;

pub struct Parser<'a> {
    lexer: Lexer<'a>,
    token: Option<Token>,
    pub errors: Vec<SyntaxError>,
}

impl<'a> Parser<'a> {
    pub fn new(src: &'a [u8]) -> Self {
        let mut p = Parser { lexer: Lexer::new(src), token: None, errors: Vec::new() };
        p.step();
        p
    }

    fn step(&mut self) {
        loop {
            match self.lexer.next_item() {
                None => {
                    self.token = None;
                    return;
                }
                Some(Ok(tok)) => {
                    self.token = Some(tok);
                    return;
                }
                Some(Err(e)) => {
                    self.errors.push(SyntaxError::Lex(e));
                }
            }
        }
    }

    fn report(&mut self, e: SyntaxError) {
        self.errors.push(e);
    }

    fn is(&self, kind: &TokenKind) -> bool {
        matches!(&self.token, Some(t) if &t.kind == kind)
    }

    fn unexpected(&self, expected: &str) -> SyntaxError {
        match &self.token {
            None => SyntaxError::UnexpectedEof,
            Some(t) => SyntaxError::Unexpected {
                token: t.kind.to_string(),
                pos: t.pos,
                expected: expected.to_string(),
            },
        }
    }

    /// Skip the current token if it is the one the error refers to.
    fn sync(&mut self, e: &SyntaxError) {
        if let (Some(pos), Some(tok)) = (e.pos(), &self.token) {
            if tok.pos == pos {
                self.step();
            }
        }
    }

    /// Skip tokens until the given kind (inclusive) or EOF.
    fn skip_until(&mut self, kind: &TokenKind) {
        loop {
            match &self.token {
                None => return,
                Some(t) if &t.kind == kind => {
                    self.step();
                    return;
                }
                _ => self.step(),
            }
        }
    }

    fn expect(&mut self, kind: &TokenKind, expected: &str) -> PResult<Pos> {
        match &self.token {
            Some(t) if &t.kind == kind => {
                let pos = t.pos;
                self.step();
                Ok(pos)
            }
            _ => Err(self.unexpected(expected)),
        }
    }

    /// Expect a closing delimiter; on failure skip until it (inclusive).
    fn expect_closing(&mut self, kind: &TokenKind, expected: &str) -> PResult<Pos> {
        match self.expect(kind, expected) {
            Ok(p) => Ok(p),
            Err(e) => {
                self.skip_until(kind);
                Err(e)
            }
        }
    }

    fn expect_identifier(&mut self) -> PResult<(Symbol, Pos)> {
        match &self.token {
            Some(Token { kind: TokenKind::Identifier(id), pos }) => {
                let r = (id.clone(), *pos);
                self.step();
                Ok(r)
            }
            _ => Err(self.unexpected("identifier")),
        }
    }

    // ------------------------------------------------------------ program

    pub fn parse_program(&mut self) -> Ast {
        let block = self.parse_block();
        if self.token.is_some() {
            let e = self.unexpected("statement");
            self.report(e);
            return Ast { statements: Vec::new() };
        }
        Ast { statements: block.0 }
    }

    fn at_block_end(&self) -> bool {
        match &self.token {
            None => true,
            Some(t) => matches!(t.kind, TokenKind::End | TokenKind::Else),
        }
    }

    fn parse_block(&mut self) -> Block {
        let mut stmts = Vec::new();
        while !self.at_block_end() {
            match self.parse_statement() {
                Ok(s) => stmts.push(s),
                Err(e) => {
                    self.report(e.clone());
                    self.sync(&e);
                    stmts.push(Statement::IllFormed);
                }
            }
        }
        Block(stmts)
    }

    fn parse_statement(&mut self) -> PResult<Statement> {
        let tok = match &self.token {
            None => return Err(SyntaxError::UnexpectedEof),
            Some(t) => t.clone(),
        };
        match tok.kind {
            TokenKind::Let => {
                self.step();
                let (name, name_pos) = match self.expect_identifier() {
                    Ok((id, p)) => (Some(id), p),
                    Err(e) => {
                        self.report(e);
                        (None, Pos::default())
                    }
                };
                let init = if self.is(&TokenKind::Assign) {
                    self.step();
                    self.parse_expr()?
                } else {
                    Expr::Literal { lit: Literal::Nil, pos: tok.pos }
                };
                Ok(Statement::Let { name, name_pos, init, pos: tok.pos })
            }
            TokenKind::Function => {
                self.step();
                match &self.token {
                    Some(Token { kind: TokenKind::Identifier(id), pos }) => {
                        let name = id.clone();
                        let name_pos = *pos;
                        self.step();
                        let func = self.parse_function_rest(tok.pos)?;
                        Ok(Statement::Let { name: Some(name), name_pos, init: func, pos: tok.pos })
                    }
                    _ => {
                        let func = self.parse_function_rest(tok.pos)?;
                        let expr = self.parse_postfix_ops(func)?;
                        let expr = self.parse_binary_rest(expr)?;
                        self.finish_expr_statement(expr)
                    }
                }
            }
            TokenKind::Return => {
                self.step();
                let expr = if self.at_block_end() && self.token.is_some() {
                    Expr::Literal { lit: Literal::Nil, pos: tok.pos }
                } else {
                    self.parse_expr()?
                };
                Ok(Statement::Return { expr, pos: tok.pos })
            }
            TokenKind::Break => {
                self.step();
                Ok(Statement::Break { pos: tok.pos })
            }
            TokenKind::While => {
                self.step();
                let condition = self.parse_recovered_expr();
                if let Err(e) = self.expect(&TokenKind::Do, "'do'") {
                    self.report(e);
                }
                let block = self.parse_block();
                self.expect_closing(&TokenKind::End, "'end'")?;
                Ok(Statement::While { condition, block, pos: tok.pos })
            }
            TokenKind::For => {
                self.step();
                let (name, name_pos) = match self.expect_identifier() {
                    Ok((id, p)) => (Some(id), p),
                    Err(e) => {
                        self.report(e);
                        (None, Pos::default())
                    }
                };
                if let Err(e) = self.expect(&TokenKind::In, "'in'") {
                    self.report(e.clone());
                    self.sync(&e);
                }
                let expr = self.parse_recovered_expr();
                if let Err(e) = self.expect(&TokenKind::Do, "'do'") {
                    self.report(e);
                }
                let block = self.parse_block();
                self.expect_closing(&TokenKind::End, "'end'")?;
                Ok(Statement::For { name, name_pos, expr, block, pos: tok.pos })
            }
            _ => {
                let expr = self.parse_expr()?;
                self.finish_expr_statement(expr)
            }
        }
    }

    fn finish_expr_statement(&mut self, expr: Expr) -> PResult<Statement> {
        if let Some(Token { kind: TokenKind::Assign, pos }) = &self.token {
            let pos = *pos;
            self.step();
            let right = self.parse_expr()?;
            Ok(Statement::Assign { left: expr, right, pos })
        } else {
            Ok(Statement::Expr(expr))
        }
    }

    /// Parse an expression, recovering errors into an ill-formed expression.
    fn parse_recovered_expr(&mut self) -> Expr {
        match self.parse_expr() {
            Ok(e) => e,
            Err(e) => {
                self.report(e);
                Expr::IllFormed
            }
        }
    }

    // ------------------------------------------------------------ expressions

    pub fn parse_expr(&mut self) -> PResult<Expr> {
        let left = self.parse_unary()?;
        self.parse_binary_rest(left)
    }

    /// Continue parsing binary operators after a complete operand.
    fn parse_binary_rest(&mut self, first: Expr) -> PResult<Expr> {
        self.parse_binary_level(first, 0)
    }

    fn binary_op_at_level(kind: &TokenKind, level: usize) -> Option<BinaryOp> {
        use TokenKind::*;
        match level {
            0 => match kind {
                Or => Some(BinaryOp::Or),
                _ => None,
            },
            1 => match kind {
                And => Some(BinaryOp::And),
                _ => None,
            },
            2 => match kind {
                EqEq => Some(BinaryOp::Equals),
                NotEq => Some(BinaryOp::NotEquals),
                Lt => Some(BinaryOp::Lower),
                Le => Some(BinaryOp::LowerEquals),
                Gt => Some(BinaryOp::Greater),
                Ge => Some(BinaryOp::GreaterEquals),
                _ => None,
            },
            3 => match kind {
                Concat => Some(BinaryOp::Concat),
                _ => None,
            },
            4 => match kind {
                Plus => Some(BinaryOp::Plus),
                Minus => Some(BinaryOp::Minus),
                _ => None,
            },
            5 => match kind {
                Star => Some(BinaryOp::Times),
                Slash => Some(BinaryOp::Div),
                Percent => Some(BinaryOp::Mod),
                _ => None,
            },
            _ => None,
        }
    }

    const MAX_LEVEL: usize = 5;

    /// Precedence climbing: `first` is an already-parsed unary operand; parse the
    /// rest of the expression at the given level and above.
    fn parse_binary_level(&mut self, first: Expr, level: usize) -> PResult<Expr> {
        // first fold higher levels
        let mut left = if level < Self::MAX_LEVEL {
            self.parse_binary_level(first, level + 1)?
        } else {
            first
        };
        loop {
            let (op, pos) = match &self.token {
                Some(t) => match Self::binary_op_at_level(&t.kind, level) {
                    Some(op) => (op, t.pos),
                    None => break,
                },
                None => break,
            };
            self.step();
            let operand = self.parse_unary()?;
            let right = if level < Self::MAX_LEVEL {
                self.parse_binary_level(operand, level + 1)?
            } else {
                operand
            };
            left = Expr::Binary { op, left: Box::new(left), right: Box::new(right), pos };
        }
        Ok(left)
    }

    fn parse_unary(&mut self) -> PResult<Expr> {
        match &self.token {
            Some(Token { kind: TokenKind::Minus, pos }) => {
                let pos = *pos;
                self.step();
                let operand = self.parse_unary()?;
                Ok(Expr::Unary { op: UnaryOp::Minus, operand: Box::new(operand), pos })
            }
            Some(Token { kind: TokenKind::Not, pos }) => {
                let pos = *pos;
                self.step();
                let operand = self.parse_unary()?;
                Ok(Expr::Unary { op: UnaryOp::Not, operand: Box::new(operand), pos })
            }
            _ => {
                let primary = self.parse_primary()?;
                self.parse_postfix_ops(primary)
            }
        }
    }

    fn parse_postfix_ops(&mut self, mut expr: Expr) -> PResult<Expr> {
        loop {
            match &self.token {
                Some(Token { kind: TokenKind::Dot, pos }) => {
                    let pos = *pos;
                    self.step();
                    let (id, id_pos) = self.expect_identifier()?;
                    let field = Expr::Literal { lit: Literal::Identifier(id), pos: id_pos };
                    expr = Expr::Access { object: Box::new(expr), field: Box::new(field), pos };
                }
                Some(Token { kind: TokenKind::OpenBracket, pos }) => {
                    let pos = *pos;
                    self.step();
                    let field = self.parse_recovered_expr();
                    self.expect_closing(&TokenKind::CloseBracket, "']'")?;
                    expr = Expr::Access { object: Box::new(expr), field: Box::new(field), pos };
                }
                Some(Token { kind: TokenKind::OpenParen, pos }) => {
                    let pos = *pos;
                    self.step();
                    let args = self.parse_expr_list(&TokenKind::CloseParen, "')'")?;
                    expr = Expr::Call { function: Box::new(expr), args, pos };
                }
                _ => return Ok(expr),
            }
        }
    }

    /// Parse a comma separated list of expressions up to the closing token (consumed).
    fn parse_expr_list(&mut self, close: &TokenKind, close_name: &str) -> PResult<Vec<Expr>> {
        let mut items = Vec::new();
        loop {
            if self.is(close) {
                self.step();
                return Ok(items);
            }
            items.push(self.parse_recovered_expr());
            if self.is(&TokenKind::Comma) {
                self.step();
                continue;
            }
            self.expect_closing(close, close_name)?;
            return Ok(items);
        }
    }

    fn parse_primary(&mut self) -> PResult<Expr> {
        let tok = match &self.token {
            None => return Err(SyntaxError::UnexpectedEof),
            Some(t) => t.clone(),
        };
        let pos = tok.pos;
        let lit = |lit: Literal| Ok(Expr::Literal { lit, pos });
        match tok.kind {
            TokenKind::Nil => {
                self.step();
                lit(Literal::Nil)
            }
            TokenKind::True => {
                self.step();
                lit(Literal::True)
            }
            TokenKind::False => {
                self.step();
                lit(Literal::False)
            }
            TokenKind::Int(i) => {
                self.step();
                lit(Literal::Int(i))
            }
            TokenKind::Float(x) => {
                self.step();
                lit(Literal::Float(x))
            }
            TokenKind::Byte(b) => {
                self.step();
                lit(Literal::Byte(b))
            }
            TokenKind::Str(s) => {
                self.step();
                lit(Literal::String(s))
            }
            TokenKind::Identifier(id) => {
                self.step();
                Ok(Expr::Identifier { name: id, pos })
            }
            TokenKind::SelfKw => {
                self.step();
                Ok(Expr::SelfKw { pos })
            }
            TokenKind::OpenParen => {
                self.step();
                let inner = self.parse_expr();
                let inner = match inner {
                    Ok(e) => Some(e),
                    Err(e) => {
                        self.report(e);
                        None
                    }
                };
                self.expect_closing(&TokenKind::CloseParen, "')'")?;
                Ok(inner.unwrap_or(Expr::IllFormed))
            }
            TokenKind::OpenBracket => {
                self.step();
                let items = self.parse_expr_list(&TokenKind::CloseBracket, "']'")?;
                lit(Literal::Array(items))
            }
            TokenKind::OpenDict => {
                self.step();
                let items = self.parse_dict_items()?;
                lit(Literal::Dict(items))
            }
            TokenKind::Function => {
                self.step();
                self.parse_function_rest(pos)
            }
            TokenKind::If => {
                self.step();
                let condition = self.parse_recovered_expr();
                if let Err(e) = self.expect(&TokenKind::Then, "'then'") {
                    self.report(e);
                }
                let then = self.parse_block();
                let otherwise = if self.is(&TokenKind::Else) {
                    self.step();
                    self.parse_block()
                } else {
                    Block(Vec::new())
                };
                self.expect_closing(&TokenKind::End, "'end'")?;
                Ok(Expr::If { condition: Box::new(condition), then, otherwise, pos })
            }
            TokenKind::OpenCommand => {
                self.step();
                let commands = self.parse_command_block_body();
                Ok(Expr::CommandBlock { kind: CommandBlockKind::Synchronous, commands, pos })
            }
            TokenKind::OpenCapture => {
                self.step();
                let commands = self.parse_command_block_body();
                Ok(Expr::CommandBlock { kind: CommandBlockKind::Capture, commands, pos })
            }
            TokenKind::OpenAsync => {
                self.step();
                let commands = self.parse_command_block_body();
                Ok(Expr::CommandBlock { kind: CommandBlockKind::Asynchronous, commands, pos })
            }
            _ => Err(self.unexpected("expression")),
        }
    }

    fn parse_dict_items(&mut self) -> PResult<Vec<(DictKey, Expr)>> {
        let mut items = Vec::new();
        loop {
            if self.is(&TokenKind::CloseBracket) {
                self.step();
                return Ok(items);
            }
            let item = self.parse_dict_item();
            items.push(item);
            if self.is(&TokenKind::Comma) {
                self.step();
                continue;
            }
            self.expect_closing(&TokenKind::CloseBracket, "']'")?;
            return Ok(items);
        }
    }

    fn parse_dict_item(&mut self) -> (DictKey, Expr) {
        let key = match self.expect_identifier() {
            Ok((id, p)) => DictKey::Ident(id, p),
            Err(e) => {
                self.report(e.clone());
                self.sync(&e);
                DictKey::IllFormed
            }
        };
        if let Err(e) = self.expect(&TokenKind::Colon, "':'") {
            self.report(e);
        }
        match self.parse_expr() {
            Ok(value) => (key, value),
            Err(e) => {
                self.report(e);
                (DictKey::IllFormed, Expr::IllFormed)
            }
        }
    }

    /// Parse `(params) block end` after the `function` keyword (and optional name).
    fn parse_function_rest(&mut self, pos: Pos) -> PResult<Expr> {
        if let Err(e) = self.expect(&TokenKind::OpenParen, "'('") {
            self.report(e);
        }
        let mut params = Vec::new();
        loop {
            if self.is(&TokenKind::CloseParen) {
                self.step();
                break;
            }
            match self.expect_identifier() {
                Ok((id, p)) => params.push(Param::Ident(id, p)),
                Err(e) => {
                    self.report(e);
                    params.push(Param::IllFormed);
                }
            }
            if self.is(&TokenKind::Comma) {
                self.step();
                continue;
            }
            self.expect_closing(&TokenKind::CloseParen, "')'")?;
            break;
        }
        let body = self.parse_block();
        self.expect_closing(&TokenKind::End, "'end'")?;
        Ok(Expr::Literal { lit: Literal::Function { params, body }, pos })
    }

    // ------------------------------------------------------------ commands

    /// Parse the commands of a block and the closing brace.
    fn parse_command_block_body(&mut self) -> Vec<Command> {
        match self.parse_commands() {
            Ok(cmds) => {
                // current token is the closing brace
                self.step();
                cmds
            }
            Err(e) => {
                self.report(e);
                self.skip_until(&TokenKind::CloseCommand);
                vec![Command::IllFormed]
            }
        }
    }

    fn at_command_end(&self) -> bool {
        match &self.token {
            None => true,
            Some(t) => matches!(
                t.kind,
                TokenKind::Semicolon | TokenKind::Pipe | TokenKind::Try | TokenKind::CloseCommand
            ),
        }
    }

    /// Skip tokens until `;`, `|` or `}` inclusive (or EOF).
    fn command_sync(&mut self) {
        loop {
            match &self.token {
                None => return,
                Some(t) => {
                    let stop = matches!(
                        t.kind,
                        TokenKind::Semicolon | TokenKind::Pipe | TokenKind::CloseCommand
                    );
                    self.step();
                    if stop {
                        return;
                    }
                }
            }
        }
    }

    fn parse_commands(&mut self) -> PResult<Vec<Command>> {
        if let Some(Token { kind: TokenKind::CloseCommand, pos }) = &self.token {
            return Err(SyntaxError::EmptyCommandBlock { pos: *pos });
        }
        let mut commands = Vec::new();
        loop {
            match self.parse_command() {
                Ok(c) => commands.push(c),
                Err(e) => {
                    self.report(e);
                    commands.push(Command::IllFormed);
                    self.command_sync();
                }
            }
            match &self.token {
                Some(Token { kind: TokenKind::Semicolon, .. }) => {
                    self.step();
                    if self.is(&TokenKind::CloseCommand) {
                        return Ok(commands);
                    }
                }
                Some(Token { kind: TokenKind::CloseCommand, .. }) => return Ok(commands),
                _ => return Err(self.unexpected("'}'")),
            }
        }
    }

    fn parse_command(&mut self) -> PResult<Command> {
        let first = self.parse_basic_command()?;
        let mut commands = vec![first];
        while self.is(&TokenKind::Pipe) {
            self.step();
            match self.parse_basic_command() {
                Ok(c) => commands.push(c),
                Err(e) => {
                    self.report(e);
                    commands.push(BasicCommand::IllFormed);
                    self.command_sync();
                    return Ok(Command::Pipeline { commands, abort_on_error: false });
                }
            }
        }
        let abort_on_error = if self.is(&TokenKind::Try) {
            self.step();
            false
        } else {
            true
        };
        Ok(Command::Pipeline { commands, abort_on_error })
    }

    fn parse_argument(&mut self) -> PResult<(Argument, Option<u8>, bool)> {
        match &self.token {
            Some(Token { kind: TokenKind::Argument(units), pos }) => {
                let pos = *pos;
                let (arg, number_like) = convert_argument(units, pos);
                let fd = if number_like {
                    // single literal of digits
                    match &arg.parts[..] {
                        [ArgPart::Literal(s)] => std::str::from_utf8(s).ok().and_then(|s| s.parse::<u8>().ok()),
                        _ => None,
                    }
                } else {
                    None
                };
                self.step();
                Ok((arg, fd, number_like))
            }
            _ => Err(self.unexpected("argument")),
        }
    }

    fn parse_basic_command(&mut self) -> PResult<BasicCommand> {
        let (program, _, _) = self.parse_argument()?;
        let pos = program.pos;
        let mut args: Vec<(Argument, Option<u8>, bool)> = Vec::new();
        let mut redirections = Vec::new();
        // arguments
        loop {
            match &self.token {
                Some(Token { kind: TokenKind::Argument(_), .. }) => {
                    let a = self.parse_argument()?;
                    args.push(a);
                }
                _ => break,
            }
        }
        // a trailing number-like argument followed by a redirection operator is its fd
        let mut pending_fd: Option<(Argument, Option<u8>)> = None;
        if matches!(&self.token, Some(Token { kind: TokenKind::Output | TokenKind::Append, .. })) {
            if let Some((_, _, true)) = args.last() {
                let (arg, fd, _) = args.pop().unwrap();
                pending_fd = Some((arg, fd));
            }
        }
        if let Some((arg, fd)) = pending_fd {
            match fd {
                Some(fd) => match self.parse_redirection_after_fd(fd) {
                    Ok(r) => redirections.push(r),
                    Err(e) => {
                        self.report(e.clone());
                        redirections.push(Redirection::IllFormed);
                        self.sync(&e);
                    }
                },
                None => {
                    let e = SyntaxError::Unexpected {
                        token: ast_to_string(&arg, 0, false).trim_matches('"').to_string(),
                        pos: arg.pos,
                        expected: "output redirection".to_string(),
                    };
                    self.report(e);
                    redirections.push(Redirection::IllFormed);
                }
            }
        }
        loop {
            match &self.token {
                None => return Err(SyntaxError::UnexpectedEof),
                Some(t)
                    if matches!(
                        t.kind,
                        TokenKind::Semicolon | TokenKind::Pipe | TokenKind::Try | TokenKind::CloseCommand
                    ) =>
                {
                    break
                }
                _ => match self.parse_redirection() {
                    Ok(r) => redirections.push(r),
                    Err(e) => {
                        self.report(e.clone());
                        redirections.push(Redirection::IllFormed);
                        self.sync(&e);
                    }
                },
            }
        }
        let args = args.into_iter().map(|(a, _, _)| a).collect();
        Ok(BasicCommand::Command { program, args, redirections, pos })
    }

    fn parse_redirection_target(&mut self) -> PResult<RedirectionTarget> {
        let (arg, fd, _) = self.parse_argument()?;
        Ok(match fd {
            Some(fd) => RedirectionTarget::Fd(fd as i64),
            None => RedirectionTarget::File(arg),
        })
    }

    fn parse_redirection_after_fd(&mut self, fd: u8) -> PResult<Redirection> {
        match &self.token {
            Some(Token { kind: TokenKind::Output, .. }) => {
                self.step();
                let target = self.parse_redirection_target()?;
                Ok(Redirection::Output { source: fd as i64, target })
            }
            Some(Token { kind: TokenKind::Append, .. }) => {
                self.step();
                let target = self.parse_redirection_target()?;
                Ok(Redirection::Append { source: fd as i64, target })
            }
            _ => Err(self.unexpected("output redirection")),
        }
    }

    fn parse_redirection(&mut self) -> PResult<Redirection> {
        match &self.token {
            Some(Token { kind: TokenKind::Output, .. }) => {
                self.step();
                let target = self.parse_redirection_target()?;
                Ok(Redirection::Output { source: 1, target })
            }
            Some(Token { kind: TokenKind::Append, .. }) => {
                self.step();
                let target = self.parse_redirection_target()?;
                Ok(Redirection::Append { source: 1, target })
            }
            Some(Token { kind: TokenKind::Input, .. }) => {
                self.step();
                let (arg, _, _) = self.parse_argument()?;
                Ok(Redirection::Input { literal: false, source: arg })
            }
            Some(Token { kind: TokenKind::HereString, .. }) => {
                self.step();
                let (arg, _, _) = self.parse_argument()?;
                Ok(Redirection::Input { literal: true, source: arg })
            }
            Some(Token { kind: TokenKind::Argument(units), pos }) => {
                let pos = *pos;
                let (arg, number_like) = convert_argument(units, pos);
                if !number_like {
                    return Err(self.unexpected("output redirection"));
                }
                let fd = match &arg.parts[..] {
                    [ArgPart::Literal(s)] => std::str::from_utf8(s).ok().and_then(|s| s.parse::<u8>().ok()),
                    _ => None,
                };
                let text = match &arg.parts[..] {
                    [ArgPart::Literal(s)] => String::from_utf8_lossy(s).to_string(),
                    _ => String::new(),
                };
                self.step();
                match fd {
                    Some(fd) => self.parse_redirection_after_fd(fd),
                    None => Err(SyntaxError::Unexpected {
                        token: text,
                        pos,
                        expected: "output redirection".to_string(),
                    }),
                }
            }
            _ => Err(self.unexpected("output redirection")),
        }
    }
}

/// Convert lexer argument units into AST parts, merging adjacent literals.
/// Also returns whether the argument is "number like" (a single unquoted literal of digits).
pub fn convert_argument(units: &[ArgUnit], pos: Pos) -> (Argument, bool) {
    let number_like = match units {
        [ArgUnit::Literal(s)] => !s.is_empty() && s.iter().all(|b| b.is_ascii_digit()),
        _ => false,
    };
    let mut parts: Vec<ArgPart> = Vec::new();
    fn push_literal(parts: &mut Vec<ArgPart>, s: &[u8]) {
        if s.is_empty() {
            return;
        }
        if let Some(ArgPart::Literal(last)) = parts.last_mut() {
            last.extend_from_slice(s);
        } else {
            parts.push(ArgPart::Literal(s.to_vec()));
        }
    }
    for u in units {
        match u {
            ArgUnit::Literal(s) | ArgUnit::SingleQuoted(s) => push_literal(&mut parts, s),
            ArgUnit::DoubleQuoted(dq) => {
                for d in dq {
                    match d {
                        DqUnit::Literal(s) => push_literal(&mut parts, s),
                        DqUnit::Dollar(id, p) => parts.push(ArgPart::Dollar(id.clone(), *p)),
                    }
                }
            }
            ArgUnit::Dollar(id, p) => parts.push(ArgPart::Dollar(id.clone(), *p)),
            ArgUnit::Star => parts.push(ArgPart::Star),
            ArgUnit::Percent => parts.push(ArgPart::Percent),
            ArgUnit::Home => parts.push(ArgPart::Home),
        }
    }
    (Argument { parts, pos }, number_like)
}
