    IllFormed,
}

impl PExpr {
    pub fn pos(&self) -> Pos {
        match self {
            PExpr::Slot { pos, .. }
            | PExpr::Literal { pos, .. }
            | PExpr::Unary { pos, .. }
            | PExpr::Binary { pos, .. }
            | PExpr::If { pos, .. }
            | PExpr::Access { pos, .. }
            | PExpr::Call { pos, .. }
            | PExpr::CommandBlock { pos, .. } => *pos,
