cat > /workspace/src/program.rs <<'EOF'
//! Semantic analysis: resolves identifiers into frame slots.

use std::collections::HashMap;
use std::fmt::Write;

use crate::ast::{self, AstDisplay, Block, DictKey, Expr, Literal, Param, Statement, Symbol, ILL_FORMED};
use crate::pos::Pos;

pub use crate::ast::{BinaryOp, CommandBlockKind, UnaryOp};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SlotKind {
    Auto,
    Capture(usize),
    SelfSlot,
}

#[derive(Debug, Clone)]
pub struct FunctionDef {
    pub params: usize,
    pub slots: Vec<SlotKind>,
    pub body: Vec<Stmt>,
    pub pos: Pos,
}

#[derive(Debug, Clone)]
pub enum PLiteral {
    Nil,
    True,
    False,
    Int(i64),
    Float(f64),
    Byte(u8),
    String(Vec<u8>),
    Array(Vec<PExpr>),
    Dict(Vec<(Symbol, PExpr)>),
    Function(std::rc::Rc<FunctionDef>),
    Identifier(Symbol),
}

#[derive(Debug, Clone)]
pub enum PExpr {
    Slot { slot: usize, pos: Pos },
    Literal { lit: PLiteral, pos: Pos },
    Unary { op: UnaryOp, operand: Box<PExpr>, pos: Pos },
    Binary { op: BinaryOp, left: Box<PExpr>, right: Box<PExpr>, pos: Pos },
    If { condition: Box<PExpr>, then: Vec<Stmt>, otherwise: Vec<Stmt>, pos: Pos },
    Access { object: Box<PExpr>, field: Box<PExpr>, pos: Pos },
    Call { function: Box<PExpr>, args: Vec<PExpr>, pos: Pos },
    CommandBlock { kind: CommandBlockKind, commands: Vec<PCommand>, pos: Pos },
    IllFormed,
}

impl PExpr {
    pub fn pos(&self) -> Pos {
        match self {
            PExpr::Slot { pos, .. }
            | PExpr::Literal { pos, .. }
            | PExpr::Unary { pos, .. }
            | PExpr::Binary { pos, .. }
            | PExpr::If { pos, .. }
            | PExpr::Access { pos, .. }
            | PExpr::Call { pos, .. }
            | PExpr::CommandBlock { pos, .. } => *pos,
            PExpr::IllFormed => Pos::default(),
        }
    }
}

#[derive(Debug, Clone)]
pub enum PArgPart {
    Literal(Vec<u8>),
    Slot(usize, Pos),
    Star,
    Percent,
    Home,
}

#[derive(Debug, Clone)]
pub struct PArgument {
    pub parts: Vec<PArgPart>,
    pub pos: Pos,
}

#[derive(Debug, Clone)]
pub enum PRedirectionTarget {
    Fd(i64),
    File(PArgument),
}

#[derive(Debug, Clone)]
pub enum PRedirection {
    Output { source: i64, target: PRedirectionTarget },
    Append { source: i64, target: PRedirectionTarget },
    Input { literal: bool, source: PArgument },
    IllFormed,
}

#[derive(Debug, Clone)]
pub enum PBasicCommand {
    Command { program: PArgument, args: Vec<PArgument>, redirections: Vec<PRedirection>, pos: Pos },
    IllFormed,
}

#[derive(Debug, Clone)]
pub enum PCommand {
    Pipeline { commands: Vec<PBasicCommand>, abort_on_error: bool },
    IllFormed,
}

#[derive(Debug, Clone)]
pub enum Stmt {
    Assign { left: PExpr, right: PExpr, pos: Pos },
    Return { expr: PExpr, pos: Pos },
    Break { pos: Pos },
    While { condition: PExpr, block: Vec<Stmt>, pos: Pos },
    For { slot: usize, expr: PExpr, block: Vec<Stmt>, pos: Pos },
    Expr(PExpr),
    IllFormed,
}

pub struct Program {
    pub slots: Vec<SlotKind>,
    pub body: Vec<Stmt>,
}

// ------------------------------------------------------------------ errors

#[derive(Debug, Clone)]
pub struct SemanticError {
    pub pos: Pos,
    pub message: String,
}

impl SemanticError {
    pub fn display(&self, path: &str) -> String {
        format!("Error: {} ({}) - {}", path, self.pos, self.message)
    }
}

// ------------------------------------------------------------------ analysis

struct Frame {
    slots: Vec<SlotKind>,
    scopes: Vec<HashMap<Symbol, usize>>,
    captures: HashMap<usize, usize>,
    self_slot: Option<usize>,
    loop_depth: usize,
}

impl Frame {
    fn new() -> Self {
        Frame {
            slots: Vec::new(),
            scopes: vec![HashMap::new()],
            captures: HashMap::new(),
            self_slot: None,
            loop_depth: 0,
        }
    }

    fn new_slot(&mut self, kind: SlotKind) -> usize {
        self.slots.push(kind);
        self.slots.len() - 1
    }
}

pub struct Analyzer {
    frames: Vec<Frame>,
    pub errors: Vec<SemanticError>,
}

impl Analyzer {
    pub fn analyze(ast: &ast::Ast) -> (Program, Vec<SemanticError>) {
        let mut a = Analyzer { frames: vec![Frame::new()], errors: Vec::new() };
        // implicit std
        a.declare_raw(std::rc::Rc::from("std"));
        let body = a.block_stmts(&ast.statements, false);
        let frame = a.frames.pop().unwrap();
        (Program { slots: frame.slots, body }, a.errors)
    }

    fn error(&mut self, pos: Pos, message: impl Into<String>) {
        self.errors.push(SemanticError { pos, message: message.into() });
    }

    fn frame(&mut self) -> &mut Frame {
        self.frames.last_mut().unwrap()
    }

    fn declare_raw(&mut self, name: Symbol) -> usize {
        let frame = self.frame();
        let slot = frame.new_slot(SlotKind::Auto);
        frame.scopes.last_mut().unwrap().insert(name, slot);
        slot
    }

    /// Declare a variable in the current scope; reports duplicates.
    fn declare(&mut self, name: &Symbol, pos: Pos) -> usize {
        let frame = self.frame();
        if let Some(&slot) = frame.scopes.last().unwrap().get(name) {
            self.error(pos, format!("duplicate variable '{}'", name));
            return slot;
        }
        self.declare_raw(name.clone())
    }

    fn resolve_in(&mut self, frame_ix: usize, name: &Symbol) -> Option<usize> {
        {
            let frame = &self.frames[frame_ix];
            for scope in frame.scopes.iter().rev() {
                if let Some(&slot) = scope.get(name) {
                    return Some(slot);
                }
            }
        }
        if frame_ix == 0 {
            return None;
        }
        let parent_slot = self.resolve_in(frame_ix - 1, name)?;
        let frame = &mut self.frames[frame_ix];
        if let Some(&slot) = frame.captures.get(&parent_slot) {
            return Some(slot);
        }
        let slot = frame.new_slot(SlotKind::Capture(parent_slot));
        frame.captures.insert(parent_slot, slot);
        Some(slot)
    }

    fn resolve(&mut self, name: &Symbol, pos: Pos) -> Option<usize> {
        let ix = self.frames.len() - 1;
        let r = self.resolve_in(ix, name);
        if r.is_none() {
            self.error(pos, format!("undeclared variable '{}'", name));
        }
        r
    }

    fn push_scope(&mut self) {
        self.frame().scopes.push(HashMap::new());
    }

    fn pop_scope(&mut self) {
        self.frame().scopes.pop();
    }

    fn block_stmts(&mut self, stmts: &[Statement], new_scope: bool) -> Vec<Stmt> {
        if new_scope {
            self.push_scope();
        }
        let mut out = Vec::new();
        for s in stmts {
            out.extend(self.statement(s));
        }
        if new_scope {
            self.pop_scope();
        }
        out
    }

    fn block(&mut self, block: &Block) -> Vec<Stmt> {
        self.block_stmts(&block.0, true)
    }

    fn statement(&mut self, stmt: &Statement) -> Vec<Stmt> {
        match stmt {
            Statement::Let { name, name_pos, init, pos } => {
                let slot = match name {
                    Some(n) => Some(self.declare(n, *name_pos)),
                    None => None,
                };
                let right = self.expr(init);
                match slot {
                    Some(slot) => {
                        vec![Stmt::Assign { left: PExpr::Slot { slot, pos: *name_pos }, right, pos: *pos }]
                    }
                    None => vec![Stmt::IllFormed],
                }
            }
            Statement::Assign { left, right, pos } => {
                let ok = matches!(left, Expr::Identifier { .. } | Expr::Access { .. } | Expr::IllFormed);
                if !ok {
                    self.error(*pos, "invalid assignment");
                }
                let l = self.expr(left);
                let r = self.expr(right);
                vec![Stmt::Assign { left: l, right: r, pos: *pos }]
            }
            Statement::Return { expr, pos } => {
                if self.frames.len() == 1 {
                    self.error(*pos, "return statement outside function");
                }
                let e = self.expr(expr);
                vec![Stmt::Return { expr: e, pos: *pos }]
            }
            Statement::Break { pos } => {
                if self.frame().loop_depth == 0 {
                    self.error(*pos, "break statement outside loop");
                }
                vec![Stmt::Break { pos: *pos }]
            }
            Statement::While { condition, block, pos } => {
                let c = self.expr(condition);
                self.frame().loop_depth += 1;
                let b = self.block(block);
                self.frame().loop_depth -= 1;
                vec![Stmt::While { condition: c, block: b, pos: *pos }]
            }
            Statement::For { name, name_pos, expr, block, pos } => {
                let e = self.expr(expr);
                self.push_scope();
                let slot = match name {
                    Some(n) => self.declare(n, *name_pos),
                    None => usize::MAX,
                };
                self.frame().loop_depth += 1;
                let b = self.block_stmts(&block.0, false);
                self.frame().loop_depth -= 1;
                self.pop_scope();
                if slot == usize::MAX {
                    vec![Stmt::IllFormed]
                } else {
                    vec![Stmt::For { slot, expr: e, block: b, pos: *pos }]
                }
            }
            Statement::Expr(e) => vec![Stmt::Expr(self.expr(e))],
            Statement::IllFormed => vec![Stmt::IllFormed],
        }
    }

    fn expr(&mut self, expr: &Expr) -> PExpr {
        match expr {
            Expr::SelfKw { pos } => {
                if self.frames.len() == 1 {
                    self.error(*pos, "self keyword outside function");
                    return PExpr::IllFormed;
                }
                let frame = self.frame();
                let slot = match frame.self_slot {
                    Some(s) => s,
                    None => {
                        let s = frame.new_slot(SlotKind::SelfSlot);
                        frame.self_slot = Some(s);
                        s
                    }
                };
                PExpr::Slot { slot, pos: *pos }
            }
            Expr::Identifier { name, pos } => match self.resolve(name, *pos) {
                Some(slot) => PExpr::Slot { slot, pos: *pos },
                None => PExpr::IllFormed,
            },
            Expr::Literal { lit, pos } => {
                let l = match lit {
                    Literal::Nil => PLiteral::Nil,
                    Literal::True => PLiteral::True,
                    Literal::False => PLiteral::False,
                    Literal::Int(i) => PLiteral::Int(*i),
                    Literal::Float(x) => PLiteral::Float(*x),
                    Literal::Byte(b) => PLiteral::Byte(*b),
                    Literal::String(s) => PLiteral::String(s.clone()),
                    Literal::Identifier(id) => PLiteral::Identifier(id.clone()),
                    Literal::Array(items) => PLiteral::Array(items.iter().map(|e| self.expr(e)).collect()),
                    Literal::Dict(items) => {
                        let mut out = Vec::new();
                        for (k, v) in items {
                            let key: Symbol = match k {
                                DictKey::Ident(s, _) => s.clone(),
                                DictKey::IllFormed => std::rc::Rc::from(ILL_FORMED),
                            };
                            let value = self.expr(v);
                            out.push((key, value));
                        }
                        PLiteral::Dict(out)
                    }
                    Literal::Function { params, body } => {
                        PLiteral::Function(std::rc::Rc::new(self.function(params, body, *pos)))
                    }
                };
                PExpr::Literal { lit: l, pos: *pos }
            }
            Expr::Unary { op, operand, pos } => {
                PExpr::Unary { op: *op, operand: Box::new(self.expr(operand)), pos: *pos }
            }
            Expr::Binary { op, left, right, pos } => {
                let l = self.expr(left);
                let r = self.expr(right);
                PExpr::Binary { op: *op, left: Box::new(l), right: Box::new(r), pos: *pos }
            }
            Expr::If { condition, then, otherwise, pos } => {
                let c = self.expr(condition);
                let t = self.block(then);
                let o = self.block(otherwise);
                PExpr::If { condition: Box::new(c), then: t, otherwise: o, pos: *pos }
            }
            Expr::Access { object, field, pos } => {
                let o = self.expr(object);
                let f = self.expr(field);
                PExpr::Access { object: Box::new(o), field: Box::new(f), pos: *pos }
            }
            Expr::Call { function, args, pos } => {
                let f = self.expr(function);
                let a = args.iter().map(|e| self.expr(e)).collect();
                PExpr::Call { function: Box::new(f), args: a, pos: *pos }
            }
            Expr::CommandBlock { kind, commands, pos } => {
                let cmds = commands.iter().map(|c| self.command(c)).collect();
                PExpr::CommandBlock { kind: *kind, commands: cmds, pos: *pos }
            }
            Expr::IllFormed => PExpr::IllFormed,
        }
    }

    fn function(&mut self, params: &[Param], body: &Block, pos: Pos) -> FunctionDef {
        self.frames.push(Frame::new());
        for p in params {
            if let Param::Ident(name, ppos) = p {
                self.declare(name, *ppos);
            }
        }
        let stmts = self.block_stmts(&body.0, false);
        let frame = self.frames.pop().unwrap();
        FunctionDef { params: params.len(), slots: frame.slots, body: stmts, pos }
    }

    fn argument(&mut self, arg: &ast::Argument) -> PArgument {
        let parts = arg
            .parts
            .iter()
            .map(|p| match p {
                ast::ArgPart::Literal(s) => PArgPart::Literal(s.clone()),
                ast::ArgPart::Dollar(name, pos) => match self.resolve(name, *pos) {
                    Some(slot) => PArgPart::Slot(slot, *pos),
                    None => PArgPart::Literal(Vec::new()),
                },
                ast::ArgPart::Star => PArgPart::Star,
                ast::ArgPart::Percent => PArgPart::Percent,
                ast::ArgPart::Home => PArgPart::Home,
            })
            .collect();
        PArgument { parts, pos: arg.pos }
    }

    fn command(&mut self, cmd: &ast::Command) -> PCommand {
        match cmd {
            ast::Command::IllFormed => PCommand::IllFormed,
            ast::Command::Pipeline { commands, abort_on_error } => {
                let cmds = commands
                    .iter()
                    .map(|c| match c {
                        ast::BasicCommand::IllFormed => PBasicCommand::IllFormed,
                        ast::BasicCommand::Command { program, args, redirections, pos } => {
                            let program = self.argument(program);
                            let args = args.iter().map(|a| self.argument(a)).collect();
                            let redirections = redirections
                                .iter()
                                .map(|r| match r {
                                    ast::Redirection::Output { source, target } => PRedirection::Output {
                                        source: *source,
                                        target: self.redirection_target(target),
                                    },
                                    ast::Redirection::Append { source, target } => PRedirection::Append {
                                        source: *source,
                                        target: self.redirection_target(target),
                                    },
                                    ast::Redirection::Input { literal, source } => PRedirection::Input {
                                        literal: *literal,
                                        source: self.argument(source),
                                    },
                                    ast::Redirection::IllFormed => PRedirection::IllFormed,
                                })
                                .collect();
                            PBasicCommand::Command { program, args, redirections, pos: *pos }
                        }
                    })
                    .collect();
                PCommand::Pipeline { commands: cmds, abort_on_error: *abort_on_error }
            }
        }
    }

    fn redirection_target(&mut self, t: &ast::RedirectionTarget) -> PRedirectionTarget {
        match t {
            ast::RedirectionTarget::Fd(fd) => PRedirectionTarget::Fd(*fd),
            ast::RedirectionTarget::File(a) => PRedirectionTarget::File(self.argument(a)),
        }
    }
}

// ------------------------------------------------------------------ printing

fn tabs(n: usize) -> String {
    "\t".repeat(n)
}

fn fmt_slots(slots: &[SlotKind], out: &mut String, indent: usize) {
    for (i, s) in slots.iter().enumerate() {
        out.push_str(&tabs(indent));
        match s {
            SlotKind::Auto => writeln!(out, "let #{}: auto", i).unwrap(),
            SlotKind::Capture(p) => writeln!(out, "let #{}: capture #{}", i, p).unwrap(),
            SlotKind::SelfSlot => writeln!(out, "let #{}: auto self", i).unwrap(),
        }
    }
}

impl AstDisplay for PExpr {
    fn fmt_ast(&self, out: &mut String, indent: usize, pretty: bool) {
        match self {
            PExpr::Slot { slot, .. } => write!(out, "#{}", slot).unwrap(),
            PExpr::Literal { lit, .. } => match lit {
                PLiteral::Array(items) => ast::fmt_array(items, out, indent, pretty),
                PLiteral::Dict(items) => {
                    let items: Vec<(String, &PExpr)> = items.iter().map(|(k, v)| (k.to_string(), v)).collect();
                    ast::fmt_dict(&items, out, indent, pretty);
                }
                PLiteral::Function(def) => {
                    write!(out, "function({})", def.params).unwrap();
                    if pretty {
                        out.push('\n');
                        fmt_slots(&def.slots, out, indent + 1);
                        // body statements, joined by newline; each on its own line
                        let mut first = true;
                        for s in &def.body {
                            if !first {
                                out.push('\n');
                            }
                            first = false;
                            out.push_str(&tabs(indent + 1));
                            s.fmt_ast(out, indent + 1, pretty);
                        }
                        out.push('\n');
                        out.push_str(&tabs(indent));
                        out.push_str("end");
                    } else {
                        // compact
                        out.push(' ');
                        for (i, s) in def.slots.iter().enumerate() {
                            match s {
                                SlotKind::Auto => write!(out, "let #{}: auto; ", i).unwrap(),
                                SlotKind::Capture(p) => write!(out, "let #{}: capture #{}; ", i, p).unwrap(),
                                SlotKind::SelfSlot => write!(out, "let #{}: auto self; ", i).unwrap(),
                            }
                        }
                        let mut first = true;
                        for s in &def.body {
                            if !first {
                                out.push_str("; ");
                            }
                            first = false;
                            s.fmt_ast(out, indent, pretty);
                        }
                        if !def.body.is_empty() {
                            out.push(' ');
                        }
                        out.push_str("end");
                    }
                }
                PLiteral::Nil => out.push_str("nil"),
                PLiteral::True => out.push_str("true"),
                PLiteral::False => out.push_str("false"),
                PLiteral::Int(i) => write!(out, "{}", i).unwrap(),
                PLiteral::Float(x) => write!(out, "{}", x).unwrap(),
                PLiteral::Byte(b) => write!(out, "'{}'", crate::pos::escape_debug_byte(*b)).unwrap(),
                PLiteral::String(s) => write!(out, "\"{}\"", crate::pos::escape_debug_bytes(s)).unwrap(),
                PLiteral::Identifier(id) => out.push_str(id),
            },
            PExpr::Unary { op, operand, .. } => {
                out.push('(');
                write!(out, "{} ", op).unwrap();
                operand.fmt_ast(out, indent, false);
                out.push(')');
            }
            PExpr::Binary { op, left, right, .. } => {
                out.push('(');
                left.fmt_ast(out, indent, false);
                write!(out, " {} ", op).unwrap();
                right.fmt_ast(out, indent, false);
                out.push(')');
            }
            PExpr::If { condition, then, otherwise, .. } => {
                ast::fmt_if(condition.as_ref(), then, otherwise, out, indent, pretty);
            }
            PExpr::Access { object, field, .. } => {
                object.fmt_ast(out, indent, false);
                match field.as_ref() {
                    PExpr::Literal { lit: PLiteral::Identifier(id), .. } => {
                        out.push('.');
                        out.push_str(id);
                    }
                    other => {
                        out.push('[');
                        other.fmt_ast(out, indent, false);
                        out.push(']');
                    }
                }
            }
            PExpr::Call { function, args, .. } => {
                function.fmt_ast(out, indent, false);
                out.push('(');
                let mut first = true;
                for a in args {
                    if !first {
                        out.push_str(", ");
                    }
                    first = false;
                    a.fmt_ast(out, indent, false);
                }
                out.push(')');
            }
            PExpr::CommandBlock { kind, commands, .. } => {
                ast::fmt_command_block(*kind, commands, out, indent, pretty);
            }
            PExpr::IllFormed => out.push_str(ILL_FORMED),
        }
    }
}

fn fmt_lvalue(expr: &PExpr, out: &mut String, indent: usize) {
    match expr {
        PExpr::Access { object, field, .. } => {
            object.fmt_ast(out, indent, false);
            out.push('[');
            field.fmt_ast(out, indent, false);
            out.push(']');
        }
        other => other.fmt_ast(out, indent, false),
    }
}

impl AstDisplay for Stmt {
    fn fmt_ast(&self, out: &mut String, indent: usize, pretty: bool) {
        match self {
            Stmt::Assign { left, right, .. } => {
                fmt_lvalue(left, out, indent);
                out.push_str(" = ");
                right.fmt_ast(out, indent, pretty);
            }
            Stmt::Return { expr, .. } => {
                out.push_str("return ");
                expr.fmt_ast(out, indent, pretty);
            }
            Stmt::Break { .. } => out.push_str("break"),
            Stmt::While { condition, block, .. } => {
                out.push_str("while ");
                condition.fmt_ast(out, indent, false);
                out.push_str(" do");
                if pretty {
                    out.push('\n');
                } else {
                    out.push(' ');
                }
                ast::fmt_block_stmts(block, out, indent, pretty);
                if pretty {
                    out.push_str(&tabs(indent));
                }
                out.push_str("end");
            }
            Stmt::For { slot, expr, block, .. } => {
                write!(out, "for #{} in ", slot).unwrap();
                expr.fmt_ast(out, indent, false);
                out.push_str(" do");
                if pretty {
                    out.push('\n');
                } else {
                    out.push(' ');
                }
                ast::fmt_block_stmts(block, out, indent, pretty);
                if pretty {
                    out.push_str(&tabs(indent));
                }
                out.push_str("end");
            }
            Stmt::Expr(e) => e.fmt_ast(out, indent, pretty),
            Stmt::IllFormed => out.push_str(ILL_FORMED),
        }
    }
}

impl AstDisplay for PCommand {
    fn fmt_ast(&self, out: &mut String, indent: usize, pretty: bool) {
        match self {
            PCommand::Pipeline { commands, abort_on_error } => {
                let mut first = true;
                for c in commands {
                    if !first {
                        out.push_str(" | ");
                    }
                    first = false;
                    c.fmt_ast(out, indent, pretty);
                }
                if !abort_on_error {
                    out.push_str(" ?");
                }
            }
            PCommand::IllFormed => {
                out.push_str(ILL_FORMED);
                out.push_str(" ?");
            }
        }
    }
}

impl AstDisplay for PBasicCommand {
    fn fmt_ast(&self, out: &mut String, indent: usize, pretty: bool) {
        match self {
            PBasicCommand::Command { program, args, redirections, .. } => {
                program.fmt_ast(out, indent, pretty);
                for a in args {
                    out.push(' ');
                    a.fmt_ast(out, indent, pretty);
                }
                for r in redirections {
                    out.push(' ');
                    r.fmt_ast(out, indent, pretty);
                }
            }
            PBasicCommand::IllFormed => out.push_str(ILL_FORMED),
        }
    }
}

impl AstDisplay for PRedirection {
    fn fmt_ast(&self, out: &mut String, indent: usize, pretty: bool) {
        match self {
            PRedirection::Output { source, target } => {
                write!(out, "{}>", source).unwrap();
                target.fmt_ast(out, indent, pretty);
            }
            PRedirection::Append { source, target } => {
                write!(out, "{}>>", source).unwrap();
                target.fmt_ast(out, indent, pretty);
            }
            PRedirection::Input { literal, source } => {
                out.push_str(if *literal { "<<" } else { "<" });
                source.fmt_ast(out, indent, pretty);
            }
            PRedirection::IllFormed => out.push_str(ILL_FORMED),
        }
    }
}

impl AstDisplay for PRedirectionTarget {
    fn fmt_ast(&self, out: &mut String, indent: usize, pretty: bool) {
        match self {
            PRedirectionTarget::Fd(fd) => write!(out, "{}", fd).unwrap(),
            PRedirectionTarget::File(a) => a.fmt_ast(out, indent, pretty),
        }
    }
}

impl AstDisplay for PArgument {
    fn fmt_ast(&self, out: &mut String, _indent: usize, _pretty: bool) {
        out.push('"');
        for p in &self.parts {
            match p {
                PArgPart::Literal(s) => out.push_str(&crate::pos::escape_debug_bytes(s)),
                PArgPart::Slot(slot, _) => write!(out, "${{#{}}}", slot).unwrap(),
                PArgPart::Star => out.push('*'),
                PArgPart::Percent => out.push('%'),
                PArgPart::Home => out.push_str("~/"),
            }
        }
        out.push('"');
    }
}

impl Program {
    pub fn to_pretty_string(&self) -> String {
        let mut out = String::new();
        fmt_slots(&self.slots, &mut out, 0);
        let mut first = true;
        for s in &self.body {
            if !first {
                out.push('\n');
            }
            first = false;
            s.fmt_ast(&mut out, 0, true);
        }
        out
    }
}
