use std::cell::RefCell;
use std::cmp::Ordering;
use std::collections::HashMap;
use std::fmt::{self, Write};
use std::hash::{Hash, Hasher};
use std::rc::Rc;

use crate::pos::{escape_debug_bytes, Pos};
use crate::program::FunctionDef;

pub type Str = Rc<Vec<u8>>;

#[derive(Clone)]
pub enum Value {
    Nil,
    Bool(bool),
    Int(i64),
    Float(f64),
    Byte(u8),
    Str(Str),
    Array(Rc<RefCell<Vec<Value>>>),
    Dict(Rc<RefCell<HashMap<Value, Value>>>),
    Function(Rc<Function>),
    Error(Rc<ErrorValue>),
}

pub struct ErrorValue {
    pub description: Str,
    pub context: Value,
}

pub type NativeFn = Rc<dyn Fn(&mut crate::runtime::interp::Interp, Vec<Value>, Value, Pos) -> Result<Value, crate::runtime::interp::Flow>>;

pub enum Function {
    Hush {
        def: Rc<FunctionDef>,
        captures: Vec<Rc<RefCell<Value>>>,
        path: Rc<str>,
    },
    /// Builtin or stateful native function, identified for display/equality by its name.
    Native { name: String, func: NativeFn },
}

impl Value {
    pub fn string(s: impl Into<Vec<u8>>) -> Value {
        Value::Str(Rc::new(s.into()))
    }

    pub fn array(items: Vec<Value>) -> Value {
        Value::Array(Rc::new(RefCell::new(items)))
    }

    pub fn dict(map: HashMap<Value, Value>) -> Value {
        Value::Dict(Rc::new(RefCell::new(map)))
    }

    pub fn error(description: impl Into<Vec<u8>>, context: Value) -> Value {
        Value::Error(Rc::new(ErrorValue { description: Rc::new(description.into()), context }))
    }

    pub fn type_name(&self) -> &'static str {
        match self {
            Value::Nil => "nil",
            Value::Bool(_) => "bool",
            Value::Int(_) => "int",
            Value::Float(_) => "float",
            Value::Byte(_) => "char",
            Value::Str(_) => "string",
            Value::Array(_) => "array",
            Value::Dict(_) => "dict",
            Value::Function(_) => "function",
            Value::Error(_) => "error",
        }
    }

    fn type_rank(&self) -> u8 {
        match self {
            Value::Nil => 0,
            Value::Bool(_) => 1,
            Value::Byte(_) => 2,
            Value::Int(_) => 3,
            Value::Float(_) => 4,
            Value::Str(_) => 5,
            Value::Array(_) => 6,
            Value::Dict(_) => 7,
            Value::Function(_) => 8,
            Value::Error(_) => 9,
        }
    }

    /// Display used for values nested in collections (strings quoted).
    pub fn fmt_nested(&self, out: &mut String) {
        match self {
            Value::Nil => out.push_str("nil"),
            Value::Bool(b) => write!(out, "{}", b).unwrap(),
            Value::Int(i) => write!(out, "{}", i).unwrap(),
            Value::Float(x) => write!(out, "{:?}", x).unwrap(),
            Value::Byte(b) => out.push(*b as char),
            Value::Str(s) => {
                out.push('"');
                out.push_str(&escape_debug_bytes(s));
                out.push('"');
            }
            Value::Array(a) => {
                let a = a.borrow();
                if a.is_empty() {
                    out.push_str("[ ]");
                } else {
                    out.push_str("[ ");
                    let mut first = true;
                    for v in a.iter() {
                        if !first {
                            out.push_str(", ");
                        }
                        first = false;
                        v.fmt_nested(out);
                    }
                    out.push_str(" ]");
                }
            }
            Value::Dict(d) => {
                let d = d.borrow();
                if d.is_empty() {
                    out.push_str("@[ ]");
                } else {
                    out.push_str("@[ ");
                    let mut first = true;
                    for (k, v) in d.iter() {
                        if !first {
                            out.push_str(", ");
                        }
                        first = false;
                        k.fmt_nested(out);
                        out.push_str(": ");
                        v.fmt_nested(out);
                    }
                    out.push_str(" ]");
                }
            }
            Value::Function(f) => f.fmt_display(out),
            Value::Error(e) => {
                out.push_str("error: \"");
                out.push_str(&escape_debug_bytes(&e.description));
                out.push_str("\" (");
                e.context.fmt_nested(out);
                out.push(')');
            }
        }
    }

    pub fn nested_string(&self) -> String {
        let mut s = String::new();
        self.fmt_nested(&mut s);
        s
    }

    /// Bytes written by std.print for a top level value.
    pub fn top_bytes(&self) -> Vec<u8> {
        match self {
            Value::Str(s) => s.as_ref().clone(),
            Value::Byte(b) => (*b as char).to_string().into_bytes(),
            other => other.nested_string().into_bytes(),
        }
    }

    pub fn compare(&self, other: &Value) -> Ordering {
        let (ra, rb) = (self.type_rank(), other.type_rank());
        if ra != rb {
            return ra.cmp(&rb);
        }
        match (self, other) {
            (Value::Nil, Value::Nil) => Ordering::Equal,
            (Value::Bool(a), Value::Bool(b)) => a.cmp(b),
            (Value::Byte(a), Value::Byte(b)) => a.cmp(b),
            (Value::Int(a), Value::Int(b)) => a.cmp(b),
            (Value::Float(a), Value::Float(b)) => a.partial_cmp(b).unwrap_or(Ordering::Equal),
            (Value::Str(a), Value::Str(b)) => a.cmp(b),
            (Value::Array(a), Value::Array(b)) => {
                let a = a.borrow();
                let b = b.borrow();
                for (x, y) in a.iter().zip(b.iter()) {
                    let c = x.compare(y);
                    if c != Ordering::Equal {
                        return c;
                    }
                }
                a.len().cmp(&b.len())
            }
            (Value::Dict(a), Value::Dict(b)) => {
                let a = a.borrow();
                let b = b.borrow();
                let mut ea: Vec<(&Value, &Value)> = a.iter().collect();
                let mut eb: Vec<(&Value, &Value)> = b.iter().collect();
                ea.sort_by(|x, y| x.0.compare(y.0).then_with(|| x.1.compare(y.1)));
                eb.sort_by(|x, y| x.0.compare(y.0).then_with(|| x.1.compare(y.1)));
                for (x, y) in ea.iter().zip(eb.iter()) {
                    let c = x.0.compare(y.0).then_with(|| x.1.compare(y.1));
                    if c != Ordering::Equal {
                        return c;
                    }
                }
                ea.len().cmp(&eb.len())
            }
            (Value::Function(a), Value::Function(b)) => a.compare(b),
            (Value::Error(a), Value::Error(b)) => {
                a.description.cmp(&b.description).then_with(|| a.context.compare(&b.context))
            }
            _ => Ordering::Equal,
        }
    }
}

impl Function {
    pub fn fmt_display(&self, out: &mut String) {
        match self {
            Function::Hush { def, path, .. } => {
                write!(out, "function<{} ({})>", path, def.pos).unwrap();
            }
            Function::Native { name, .. } => out.push_str(name),
        }
    }

    pub fn display_string(&self) -> String {
        let mut s = String::new();
        self.fmt_display(&mut s);
        s
    }

    fn compare(&self, other: &Function) -> Ordering {
        match (self, other) {
            (Function::Hush { def: a, captures: ca, .. }, Function::Hush { def: b, captures: cb, .. }) => {
                let c = (a.pos.line, a.pos.column).cmp(&(b.pos.line, b.pos.column));
                if c != Ordering::Equal {
                    return c;
                }
                for (x, y) in ca.iter().zip(cb.iter()) {
                    let c = x.borrow().compare(&y.borrow());
                    if c != Ordering::Equal {
                        return c;
                    }
                }
                ca.len().cmp(&cb.len())
            }
            (Function::Hush { .. }, Function::Native { .. }) => Ordering::Less,
            (Function::Native { .. }, Function::Hush { .. }) => Ordering::Greater,
            (Function::Native { name: a, .. }, Function::Native { name: b, .. }) => a.cmp(b),
        }
    }
}

impl PartialEq for Value {
    fn eq(&self, other: &Value) -> bool {
        match (self, other) {
            (Value::Nil, Value::Nil) => true,
            (Value::Bool(a), Value::Bool(b)) => a == b,
            (Value::Int(a), Value::Int(b)) => a == b,
            (Value::Float(a), Value::Float(b)) => a == b || (a.is_nan() && b.is_nan()),
            (Value::Byte(a), Value::Byte(b)) => a == b,
            (Value::Str(a), Value::Str(b)) => a == b,
            (Value::Array(a), Value::Array(b)) => {
                if Rc::ptr_eq(a, b) {
                    return true;
                }
                let a = a.borrow();
                let b = b.borrow();
                a.len() == b.len() && a.iter().zip(b.iter()).all(|(x, y)| x == y)
            }
            (Value::Dict(a), Value::Dict(b)) => {
                if Rc::ptr_eq(a, b) {
                    return true;
                }
                let a = a.borrow();
                let b = b.borrow();
                a.len() == b.len() && a.iter().all(|(k, v)| b.get(k).map_or(false, |v2| v == v2))
            }
            (Value::Function(a), Value::Function(b)) => match (a.as_ref(), b.as_ref()) {
                (Function::Hush { def: da, captures: ca, .. }, Function::Hush { def: db, captures: cb, .. }) => {
                    Rc::ptr_eq(da, db)
                        && ca.len() == cb.len()
                        && ca.iter().zip(cb.iter()).all(|(x, y)| *x.borrow() == *y.borrow())
                }
                (Function::Native { name: a, .. }, Function::Native { name: b, .. }) => a == b,
                _ => false,
            },
            (Value::Error(a), Value::Error(b)) => a.description == b.description && a.context == b.context,
            _ => false,
        }
    }
}

impl Eq for Value {}

impl Hash for Value {
    fn hash<H: Hasher>(&self, state: &mut H) {
        std::mem::discriminant(self).hash(state);
        match self {
            Value::Nil => {}
            Value::Bool(b) => b.hash(state),
            Value::Int(i) => i.hash(state),
            Value::Float(x) => {
                let x = if *x == 0.0 { 0.0 } else if x.is_nan() { f64::NAN } else { *x };
                x.to_bits().hash(state)
            }
            Value::Byte(b) => b.hash(state),
            Value::Str(s) => s.hash(state),
            Value::Array(a) => {
                for v in a.borrow().iter() {
                    v.hash(state);
                }
            }
            Value::Dict(d) => {
                // order independent hash
                let mut acc: u64 = 0;
                for (k, v) in d.borrow().iter() {
                    let mut h = std::collections::hash_map::DefaultHasher::new();
                    k.hash(&mut h);
                    v.hash(&mut h);
                    acc = acc.wrapping_add(h.finish());
                }
                acc.hash(state);
            }
            Value::Function(f) => match f.as_ref() {
                Function::Hush { def, captures, .. } => {
                    def.pos.line.hash(state);
                    def.pos.column.hash(state);
                    for c in captures {
                        c.borrow().hash(state);
                    }
                }
                Function::Native { name, .. } => name.hash(state),
            },
            Value::Error(e) => {
                e.description.hash(state);
                e.context.hash(state);
            }
        }
    }
}

impl fmt::Debug for Value {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{}", self.nested_string())
    }
}
