cat > /workspace/src/runtime/interp.rs <<'EOF'
use std::cell::RefCell;
use std::collections::HashMap;
use std::fmt;
use std::io::Write;
use std::path::PathBuf;
use std::rc::Rc;

use rand::SeedableRng;

use crate::pos::Pos;
use crate::program::*;

use super::value::{Function, Str, Value};

pub struct Panic {
    pub message: String,
    pub pos: Pos,
    pub path: Rc<str>,
}

impl fmt::Display for Panic {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "Panic in {} ({}): {}", self.path, self.pos, self.message)
    }
}

pub enum Flow {
    Return(Value),
    Break,
    Panic(Panic),
    Exit(i32),
}

pub type EvalResult = Result<Value, Flow>;

pub struct Frame {
    pub slots: Vec<Rc<RefCell<Value>>>,
    pub path: Rc<str>,
}

pub struct Interp {
    pub frames: Vec<Frame>,
    pub args: Vec<String>,
    pub modules: HashMap<PathBuf, Value>,
    pub rng: rand_chacha::ChaCha8Rng,
    pub std: Value,
    pub main_path: Rc<str>,
}

impl Interp {
    pub fn new(args: Vec<String>) -> Self {
        let mut interp = Interp {
            frames: Vec::new(),
            args,
            modules: HashMap::new(),
            rng: rand_chacha::ChaCha8Rng::from_entropy(),
            std: Value::Nil,
            main_path: Rc::from(""),
        };
        interp.std = super::stdlib::make_std();
        interp
    }

    pub fn flush_stdout(&self) {
        let _ = std::io::stdout().flush();
    }

    pub fn current_path(&self) -> Rc<str> {
        match self.frames.last() {
            Some(f) => f.path.clone(),
            None => self.main_path.clone(),
        }
    }

    pub fn panic(&self, pos: Pos, message: impl Into<String>) -> Flow {
        Flow::Panic(Panic { message: message.into(), pos, path: self.current_path() })
    }

    pub fn type_error(&self, pos: Pos, value: &Value, expected: &str) -> Flow {
        self.panic(pos, format!("value ({}) has unexpected type, expected {}", value.nested_string(), expected))
    }

    pub fn invalid_value(&self, pos: Pos, value: &Value, expected: &str) -> Flow {
        self.panic(pos, format!("invalid value ({}), expected {}", value.nested_string(), expected))
    }

    pub fn index_out_of_bounds(&self, pos: Pos, index: &Value) -> Flow {
        self.panic(pos, format!("index ({}) out of bounds", index.nested_string()))
    }

    pub fn arity_error(&self, pos: Pos, supplied: usize, expected: usize) -> Flow {
        self.panic(
            pos,
            format!("incorrect amount of function parameters -- supplied {}, expected {}", supplied, expected),
        )
    }

    /// Run a whole program (main script or module). Returns the value of the last statement.
    pub fn run_program(&mut self, program: &Program, path: Rc<str>) -> EvalResult {
        if self.frames.is_empty() {
            self.main_path = path.clone();
        }
        let mut slots = Vec::with_capacity(program.slots.len());
        for (i, _) in program.slots.iter().enumerate() {
            let v = if i == 0 { self.std.clone() } else { Value::Nil };
            slots.push(Rc::new(RefCell::new(v)));
        }
        self.frames.push(Frame { slots, path });
        let result = self.exec_block(&program.body);
        self.frames.pop();
        match result {
            Err(Flow::Return(v)) => Ok(v),
            Err(Flow::Break) => Ok(Value::Nil),
            other => other,
        }
    }

    fn slot(&self, slot: usize) -> Rc<RefCell<Value>> {
        self.frames.last().unwrap().slots[slot].clone()
    }

    /// Execute statements, returning the value of the last expression statement.
    pub fn exec_block(&mut self, stmts: &[Stmt]) -> EvalResult {
        let mut last = Value::Nil;
        for s in stmts {
            last = self.exec_stmt(s)?;
        }
        Ok(last)
    }

    fn exec_stmt(&mut self, stmt: &Stmt) -> EvalResult {
        match stmt {
            Stmt::Assign { left, right, .. } => {
                let value = self.eval(right)?;
                self.assign(left, value)?;
                Ok(Value::Nil)
            }
            Stmt::Return { expr, .. } => {
                let v = self.eval(expr)?;
                Err(Flow::Return(v))
            }
            Stmt::Break { .. } => Err(Flow::Break),
            Stmt::While { condition, block, .. } => {
                loop {
                    let c = self.eval(condition)?;
                    match c {
                        Value::Bool(true) => {}
                        Value::Bool(false) => break,
                        other => {
                            return Err(self.panic(
                                condition.pos(),
                                format!("condition ({}) is not a boolean", other.nested_string()),
                            ))
                        }
                    }
                    match self.exec_block(block) {
                        Ok(_) => {}
                        Err(Flow::Break) => break,
                        Err(e) => return Err(e),
                    }
                }
                Ok(Value::Nil)
            }
            Stmt::For { slot, expr, block, .. } => {
                let iter = self.eval(expr)?;
                let pos = expr.pos();
                if !matches!(iter, Value::Function(_)) {
                    return Err(self.type_error(pos, &iter, "function"));
                }
                loop {
                    let step = self.call(&iter, Vec::new(), Value::Nil, pos)?;
                    let dict = match &step {
                        Value::Dict(d) => d.clone(),
                        other => return Err(self.type_error(pos, other, "dict")),
                    };
                    let finished_key = Value::string(b"finished".to_vec());
                    let finished = match dict.borrow().get(&finished_key) {
                        Some(v) => v.clone(),
                        None => return Err(self.index_out_of_bounds(pos, &finished_key)),
                    };
                    match finished {
                        Value::Bool(true) => break,
                        Value::Bool(false) => {}
                        other => return Err(self.type_error(pos, &other, "bool")),
                    }
                    let value_key = Value::string(b"value".to_vec());
                    let value = match dict.borrow().get(&value_key) {
                        Some(v) => v.clone(),
                        None => return Err(self.index_out_of_bounds(pos, &value_key)),
                    };
                    *self.slot(*slot).borrow_mut() = value;
                    match self.exec_block(block) {
                        Ok(_) => {}
                        Err(Flow::Break) => break,
                        Err(e) => return Err(e),
                    }
                }
                Ok(Value::Nil)
            }
            Stmt::Expr(e) => self.eval(e),
            Stmt::IllFormed => Ok(Value::Nil),
        }
    }

    fn assign(&mut self, left: &PExpr, value: Value) -> Result<(), Flow> {
        match left {
            PExpr::Slot { slot, .. } => {
                *self.slot(*slot).borrow_mut() = value;
                Ok(())
            }
            PExpr::Access { object, field, pos } => {
                let obj = self.eval(object)?;
                let key = self.eval(field)?;
                match &obj {
                    Value::Array(a) => {
                        let index = match key {
                            Value::Int(i) => i,
                            other => return Err(self.type_error(field.pos(), &other, "int")),
                        };
                        if index < 0 {
                            return Err(self.index_out_of_bounds(*pos, &Value::Int(index)));
                        }
                        let mut a = a.borrow_mut();
                        let ix = index as usize;
                        if ix >= a.len() {
                            return Err(self.index_out_of_bounds(field.pos(), &Value::Int(index)));
                        }
                        a[ix] = value;
                        Ok(())
                    }
                    Value::Dict(d) => {
                        d.borrow_mut().insert(key, value);
                        Ok(())
                    }
                    Value::Error(_) => Err(self.panic(
                        field.pos(),
                        format!("attempt to assign field ({}), which is readonly", key.nested_string()),
                    )),
                    other => Err(self.type_error(object.pos(), other, "array, dict or error")),
                }
            }
            PExpr::IllFormed => Ok(()),
            _ => Ok(()),
        }
    }

    pub fn eval(&mut self, expr: &PExpr) -> EvalResult {
        match expr {
            PExpr::Slot { slot, .. } => Ok(self.slot(*slot).borrow().clone()),
            PExpr::Literal { lit, pos } => self.eval_literal(lit, *pos),
            PExpr::Unary { op, operand, .. } => {
                let v = self.eval(operand)?;
                match op {
                    UnaryOp::Minus => match v {
                        Value::Int(i) => Ok(Value::Int(i.wrapping_neg())),
                        Value::Float(x) => Ok(Value::Float(-x)),
                        other => Err(self.type_error(operand.pos(), &other, "int or float")),
                    },
                    UnaryOp::Not => match v {
                        Value::Bool(b) => Ok(Value::Bool(!b)),
                        other => Err(self.type_error(operand.pos(), &other, "bool")),
                    },
                }
            }
            PExpr::Binary { op, left, right, pos } => self.eval_binary(*op, left, right, *pos),
            PExpr::If { condition, then, otherwise, .. } => {
                let c = self.eval(condition)?;
                match c {
                    Value::Bool(true) => self.exec_block(then),
                    Value::Bool(false) => self.exec_block(otherwise),
                    other => Err(self.panic(
                        condition.pos(),
                        format!("condition ({}) is not a boolean", other.nested_string()),
                    )),
                }
            }
            PExpr::Access { object, field, .. } => {
                let obj = self.eval(object)?;
                let key = self.eval(field)?;
                self.index(&obj, &key, object.pos(), field.pos())
            }
            PExpr::Call { function, args, pos } => {
                let (func, self_val) = match function.as_ref() {
                    PExpr::Access { object, field, .. } => {
                        let obj = self.eval(object)?;
                        let key = self.eval(field)?;
                        let f = self.index(&obj, &key, object.pos(), field.pos())?;
                        (f, obj)
                    }
                    other => (self.eval(other)?, Value::Nil),
                };
                let mut argv = Vec::with_capacity(args.len());
                for a in args {
                    argv.push(self.eval(a)?);
                }
                if !matches!(func, Value::Function(_)) {
                    return Err(self.panic(
                        function.pos(),
                        format!("attempt to call ({}), which is not a function", func.nested_string()),
                    ));
                }
                self.call(&func, argv, self_val, *pos)
            }
            PExpr::CommandBlock { kind, commands, pos } => super::command::run_block(self, *kind, commands, *pos),
            PExpr::IllFormed => Ok(Value::Nil),
        }
    }

    pub fn index(&self, obj: &Value, key: &Value, obj_pos: Pos, key_pos: Pos) -> EvalResult {
        match obj {
            Value::Str(s) => {
                let i = match key {
                    Value::Int(i) => *i,
                    other => return Err(self.type_error(key_pos, other, "int")),
                };
                if i < 0 || i as usize >= s.len() {
                    return Err(self.index_out_of_bounds(key_pos, key));
                }
                Ok(Value::Byte(s[i as usize]))
            }
            Value::Array(a) => {
                let i = match key {
                    Value::Int(i) => *i,
                    other => return Err(self.type_error(key_pos, other, "int")),
                };
                let a = a.borrow();
                if i < 0 || i as usize >= a.len() {
                    return Err(self.index_out_of_bounds(key_pos, key));
                }
                Ok(a[i as usize].clone())
            }
            Value::Dict(d) => match d.borrow().get(key) {
                Some(v) => Ok(v.clone()),
                None => Err(self.index_out_of_bounds(key_pos, key)),
            },
            Value::Error(e) => match key {
                Value::Str(s) if s.as_slice() == b"description" => Ok(Value::Str(e.description.clone())),
                Value::Str(s) if s.as_slice() == b"context" => Ok(e.context.clone()),
                _ => Err(self.index_out_of_bounds(key_pos, key)),
            },
            other => Err(self.type_error(obj_pos, other, "string, array, dict or error")),
        }
    }

    fn eval_literal(&mut self, lit: &PLiteral, pos: Pos) -> EvalResult {
        Ok(match lit {
            PLiteral::Nil => Value::Nil,
            PLiteral::True => Value::Bool(true),
            PLiteral::False => Value::Bool(false),
            PLiteral::Int(i) => Value::Int(*i),
            PLiteral::Float(x) => Value::Float(*x),
            PLiteral::Byte(b) => Value::Byte(*b),
            PLiteral::String(s) => Value::string(s.clone()),
            PLiteral::Identifier(id) => Value::string(id.as_bytes().to_vec()),
            PLiteral::Array(items) => {
                let mut out = Vec::with_capacity(items.len());
                for e in items {
                    out.push(self.eval(e)?);
                }
                Value::array(out)
            }
            PLiteral::Dict(items) => {
                let mut map = HashMap::new();
                for (k, v) in items {
                    let value = self.eval(v)?;
                    map.insert(Value::string(k.as_bytes().to_vec()), value);
                }
                Value::dict(map)
            }
            PLiteral::Function(def) => {
                let frame = self.frames.last().unwrap();
                let mut captures = Vec::new();
                for s in &def.slots {
                    if let SlotKind::Capture(p) = s {
                        captures.push(frame.slots[*p].clone());
                    }
                }
                let _ = pos;
                Value::Function(Rc::new(Function::Hush { def: def.clone(), captures, path: frame.path.clone() }))
            }
        })
    }

    fn eval_binary(&mut self, op: BinaryOp, left: &PExpr, right: &PExpr, pos: Pos) -> EvalResult {
        match op {
            BinaryOp::And | BinaryOp::Or => {
                let l = self.eval(left)?;
                let lb = match l {
                    Value::Bool(b) => b,
                    other => return Err(self.type_error(left.pos(), &other, "bool")),
                };
                if (op == BinaryOp::And && !lb) || (op == BinaryOp::Or && lb) {
                    return Ok(Value::Bool(lb));
                }
                let r = self.eval(right)?;
                match r {
                    Value::Bool(b) => Ok(Value::Bool(b)),
                    other => Err(self.type_error(right.pos(), &other, "bool")),
                }
            }
            _ => {
                let l = self.eval(left)?;
                let r = self.eval(right)?;
                self.binary_values(op, l, r, left.pos(), right.pos(), pos)
            }
        }
    }

    pub fn binary_values(&self, op: BinaryOp, l: Value, r: Value, lpos: Pos, rpos: Pos, pos: Pos) -> EvalResult {
        use BinaryOp::*;
        match op {
            Plus | Minus | Times | Div | Mod => match l {
                Value::Int(a) => {
                    let b = match r {
                        Value::Int(b) => b,
                        other => return Err(self.type_error(rpos, &other, "int")),
                    };
                    let res = match op {
                        Plus => a.checked_add(b),
                        Minus => a.checked_sub(b),
                        Times => a.checked_mul(b),
                        Div => {
                            return match a.checked_div(b) {
                                Some(v) => Ok(Value::Int(v)),
                                None => Err(self.panic(pos, "division by zero")),
                            }
                        }
                        Mod => {
                            return match a.checked_rem(b) {
                                Some(v) => Ok(Value::Int(v)),
                                None => Err(self.panic(pos, "division by zero")),
                            }
                        }
                        _ => unreachable!(),
                    };
                    match res {
                        Some(v) => Ok(Value::Int(v)),
                        None => Err(self.panic(pos, "integer overflow")),
                    }
                }
                Value::Float(a) => {
                    let b = match r {
                        Value::Float(b) => b,
                        other => return Err(self.type_error(rpos, &other, "float")),
                    };
                    Ok(Value::Float(match op {
                        Plus => a + b,
                        Minus => a - b,
                        Times => a * b,
                        Div => a / b,
                        Mod => a % b,
                        _ => unreachable!(),
                    }))
                }
                other => Err(self.type_error(lpos, &other, "int or float")),
            },
            Equals => Ok(Value::Bool(l == r)),
            NotEquals => Ok(Value::Bool(l != r)),
            Lower | LowerEquals | Greater | GreaterEquals => {
                let ord = match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => a.cmp(b),
                    (Value::Int(_), other) => return Err(self.type_error(rpos, other, "int")),
                    (Value::Float(a), Value::Float(b)) => match a.partial_cmp(b) {
                        Some(o) => o,
                        None => return Ok(Value::Bool(false)),
                    },
                    (Value::Float(_), other) => return Err(self.type_error(rpos, other, "float")),
                    (Value::Byte(a), Value::Byte(b)) => a.cmp(b),
                    (Value::Byte(_), other) => return Err(self.type_error(rpos, other, "char")),
                    (Value::Str(a), Value::Str(b)) => a.cmp(b),
                    (Value::Str(_), other) => return Err(self.type_error(rpos, other, "string")),
                    (other, _) => return Err(self.type_error(lpos, other, "int, float, byte or string")),
                };
                Ok(Value::Bool(match op {
                    Lower => ord == std::cmp::Ordering::Less,
                    LowerEquals => ord != std::cmp::Ordering::Greater,
                    Greater => ord == std::cmp::Ordering::Greater,
                    GreaterEquals => ord != std::cmp::Ordering::Less,
                    _ => unreachable!(),
                }))
            }
            Concat => {
                let a = match &l {
                    Value::Str(s) => s.clone(),
                    other => return Err(self.type_error(lpos, other, "string")),
                };
                let b = match &r {
                    Value::Str(s) => s.clone(),
                    other => return Err(self.type_error(rpos, other, "string")),
                };
                let mut out = Vec::with_capacity(a.len() + b.len());
                out.extend_from_slice(&a);
                out.extend_from_slice(&b);
                Ok(Value::string(out))
            }
            And | Or => unreachable!(),
        }
    }

    /// Call a function value.
    pub fn call(&mut self, func: &Value, args: Vec<Value>, self_val: Value, pos: Pos) -> EvalResult {
        let f = match func {
            Value::Function(f) => f.clone(),
            other => {
                return Err(self.panic(
                    pos,
                    format!("attempt to call ({}), which is not a function", other.nested_string()),
                ))
            }
        };
        match f.as_ref() {
            Function::Hush { def, captures, path } => {
                if args.len() != def.params {
                    return Err(self.arity_error(pos, args.len(), def.params));
                }
                let mut slots = Vec::with_capacity(def.slots.len());
                let mut cap_iter = captures.iter();
                let mut arg_iter = args.into_iter();
                for s in &def.slots {
                    match s {
                        SlotKind::Auto => {
                            let v = arg_iter.next().unwrap_or(Value::Nil);
                            slots.push(Rc::new(RefCell::new(v)));
                        }
                        SlotKind::Capture(_) => {
                            slots.push(cap_iter.next().cloned().unwrap_or_else(|| Rc::new(RefCell::new(Value::Nil))));
                        }
                        SlotKind::SelfSlot => slots.push(Rc::new(RefCell::new(self_val.clone()))),
                    }
                }
                // parameters occupy the first `params` auto slots; args beyond params already checked
                self.frames.push(Frame { slots, path: path.clone() });
                let result = self.exec_block(&def.body);
                self.frames.pop();
                match result {
                    Ok(v) => Ok(v),
                    Err(Flow::Return(v)) => Ok(v),
                    Err(Flow::Break) => Ok(Value::Nil),
                    Err(e) => Err(e),
                }
            }
            Function::Native { func, .. } => {
                let func = func.clone();
                func(self, args, self_val, pos)
            }
        }
    }

    pub fn str_arg(&self, v: &Value, pos: Pos) -> Result<Str, Flow> {
        match v {
            Value::Str(s) => Ok(s.clone()),
            other => Err(self.type_error(pos, other, "string")),
        }
    }

    pub fn int_arg(&self, v: &Value, pos: Pos) -> Result<i64, Flow> {
        match v {
            Value::Int(i) => Ok(*i),
            other => Err(self.type_error(pos, other, "int")),
        }
    }
}
