fn std_substr(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 3, pos)?;
    let s = interp.str_arg(&args[0], pos)?;
    let start = interp.int_arg(&args[1], pos)?;
    let len = interp.int_arg(&args[2], pos)?;
    if start < 0 || len < 0 {
        return Ok(Value::Nil);
    }
    let (start, len) = (start as usize, len as usize);
    match start.checked_add(len) {
        Some(end) if end <= s.len() => Ok(Value::string(s[start..end].to_vec())),
        _ => Ok(Value::Nil),
    }
}

fn split_bytes(s: &[u8], pat: &[u8]) -> Vec<Vec<u8>> {
    if pat.is_empty() {
        // like Rust's str::split("") : empty, each char, empty
        let mut out = vec![Vec::new()];
        for b in s {
            out.push(vec![*b]);
        }
        out.push(Vec::new());
        return out;
    }
    let mut out = Vec::new();
    let mut start = 0;
    let mut i = 0;
    while i + pat.len() <= s.len() {
        if &s[i..i + pat.len()] == pat {
            out.push(s[start..i].to_vec());
            i += pat.len();
            start = i;
        } else {
            i += 1;
        }
    }
    out.push(s[start..].to_vec());
    out
}

fn std_split(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 2, pos)?;
    let s = interp.str_arg(&args[0], pos)?;
    let pat = interp.str_arg(&args[1], pos)?;
    Ok(Value::array(split_bytes(&s, &pat).into_iter().map(Value::string).collect()))
}

fn std_trim(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    let s = interp.str_arg(&args[0], pos)?;
    let start = s.iter().position(|b| !b.is_ascii_whitespace()).unwrap_or(s.len());
    let end = s.iter().rposition(|b| !b.is_ascii_whitespace()).map(|p| p + 1).unwrap_or(start);
    Ok(Value::string(s[start..end.max(start)].to_vec()))
}

fn std_replace(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 3, pos)?;
    let s = interp.str_arg(&args[0], pos)?;
    let pat = interp.str_arg(&args[1], pos)?;
    let rep = interp.str_arg(&args[2], pos)?;
    let parts = split_bytes(&s, &pat);
    let mut out = Vec::new();
    for (i, p) in parts.iter().enumerate() {
        if i > 0 {
            out.extend_from_slice(&rep);
        }
        out.extend_from_slice(p);
    }
    Ok(Value::string(out))
}

fn std_contains(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 2, pos)?;
    match &args[0] {
        Value::Str(s) => match &args[1] {
            Value::Byte(b) => Ok(Value::Bool(s.contains(b))),
            other => Err(interp.type_error(pos, other, "char")),
        },
        Value::Array(a) => Ok(Value::Bool(a.borrow().contains(&args[1]))),
        Value::Dict(d) => Ok(Value::Bool(d.borrow().contains_key(&args[1]))),
        other => Err(interp.type_error(pos, other, "string ,array or dict")),
    }
}

fn std_sort(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    match &args[0] {
        Value::Array(a) => {
            a.borrow_mut().sort_by(|x, y| x.compare(y));
            Ok(Value::Nil)
        }
        other => Err(interp.type_error(pos, other, "array")),
    }
}

fn std_bind(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 2, pos)?;
    let obj = args[0].clone();
    let func = args[1].clone();
    if !matches!(func, Value::Function(_)) {
        return Err(interp.type_error(pos, &func, "function"));
    }
    Ok(native("std.bind<impl>", move |interp, args, _, pos| interp.call(&func, args, obj.clone(), pos)))
}

