fn std_env(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    let name = interp.str_arg(&args[0], pos)?;
    use std::os::unix::ffi::OsStrExt;
    let os = std::ffi::OsStr::from_bytes(&name);
