fn std_glob(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    let pat = interp.str_arg(&args[0], pos)?;
    let pat = String::from_utf8_lossy(&pat).to_string();
    use std::os::unix::ffi::OsStrExt;
    match glob::glob(&pat) {
        Ok(paths) => {
            let mut out = Vec::new();
            for p in paths {
                match p {
                    Ok(p) => out.push(Value::string(p.as_os_str().as_bytes().to_vec())),
                    Err(e) => return Ok(Value::error(e.to_string(), Value::Nil)),
                }
            }
            Ok(Value::array(out))
        }
        Err(e) => Ok(Value::error("Invalid pattern", key(e.msg))),
    }
}

fn std_read(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    if args.len() > 1 {
        return Err(interp.arity_error(pos, args.len(), 1));
    }
    if let Some(prompt) = args.first() {
        let p = interp.str_arg(prompt, pos)?;
        let stdout = std::io::stdout();
        let mut out = stdout.lock();
        let _ = out.write_all(&p);
        let _ = out.flush();
    }
    let mut line = Vec::new();
    let stdin = std::io::stdin();
    let mut lock = stdin.lock();
    use std::io::BufRead;
    match lock.read_until(b'\n', &mut line) {
        Ok(_) => Ok(Value::string(line)),
        Err(e) => Err(interp.panic(pos, e.to_string())),
    }
}

fn std_exit(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    let code = interp.int_arg(&args[0], pos)?;
    if !(0..=255).contains(&code) {
        return Err(interp.invalid_value(pos, &args[0], "valid exit code"));
    }
    Err(Flow::Exit(code as i32))
}

fn std_args(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
