// ------------------------------------------------------------------ import

fn std_import(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    let p = interp.str_arg(&args[0], pos)?;
    use std::os::unix::ffi::OsStrExt;
    let rel = std::path::PathBuf::from(std::ffi::OsStr::from_bytes(&p));
    let current = interp.current_path();
    let base = std::path::Path::new(current.as_ref());
    let joined = if rel.is_absolute() {
        rel
    } else {
        match base.parent() {
            Some(dir) if current.as_ref() != "<stdin>" => dir.join(&rel),
            _ => rel,
        }
    };
    let canonical = match joined.canonicalize() {
        Ok(c) => c,
        Err(e) => return Err(interp.panic(pos, e.to_string())),
    };
    if let Some(v) = interp.modules.get(&canonical) {
        return Ok(v.clone());
    }
    let source = match std::fs::read(&canonical) {
        Ok(s) => s,
        Err(e) => return Err(interp.panic(pos, e.to_string())),
    };
    let path_str = canonical.to_string_lossy().to_string();
    let mut parser = crate::parser::Parser::new(&source);
    let ast = parser.parse_program();
    let syntax_errors = parser.errors;
    {
        let stderr = std::io::stderr();
        let mut err = stderr.lock();
        for e in syntax_errors.iter().take(20) {
            let _ = writeln!(err, "{}", e.display(&path_str));
        }
        if syntax_errors.len() > 20 {
            let _ = writeln!(err, "20 more supressed syntax errors");
        }
    }
    let analysis = crate::program::Analyzer::analyze(&ast);
    {
        let stderr = std::io::stderr();
        let mut err = stderr.lock();
        for e in &analysis.errors {
            let _ = writeln!(err, "{}", e.display(&path_str));
        }
    }
    if !syntax_errors.is_empty() || !analysis.errors.is_empty() || analysis.failed {
        return Err(interp.panic(pos, format!("failed to import module ({})", path_str)));
    }
    let saved_args = std::mem::take(&mut interp.args);
    let result = interp.run_program(&analysis.program, Rc::from(path_str.as_str()));
    interp.args = saved_args;
    let value = result?;
    interp.modules.insert(canonical, value.clone());
    Ok(value)
}

