    add("import", std_import);
    add("sleep", std_sleep);
    add("rand", std_rand);
    add("randint", std_randint);
    add("randseed", std_randseed);
    add("regex", std_regex);

    let mut json = HashMap::new();
    json.insert(key("encode"), native("std.json.encode", json_encode));
    json.insert(key("decode"), native("std.json.decode", json_decode));
    m.insert(key("json"), Value::dict(json));

    let mut b64 = HashMap::new();
    b64.insert(key("encode"), native("std.base64.encode", base64_encode));
    b64.insert(key("decode"), native("std.base64.decode", base64_decode));
    m.insert(key("base64"), Value::dict(b64));

    let mut hexd = HashMap::new();
    hexd.insert(key("encode"), native("std.hex.encode", hex_encode));
    hexd.insert(key("decode"), native("std.hex.decode", hex_decode));
    m.insert(key("hex"), Value::dict(hexd));

    Value::dict(m)
}

// ------------------------------------------------------------------ printing

fn print_values(args: &Args, newline: bool) {
    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    let mut first = true;
    for v in args {
        if !first {
            let _ = out.write_all(b"\t");
        }
        first = false;
        let _ = out.write_all(&v.top_bytes());
    }
    if newline {
        let _ = out.write_all(b"\n");
    }
}

fn std_print(_: &mut Interp, args: Args, _: Value, _: Pos) -> EvalResult {
    print_values(&args, false);
    Ok(Value::Nil)
}

fn std_println(_: &mut Interp, args: Args, _: Value, _: Pos) -> EvalResult {
    print_values(&args, true);
    Ok(Value::Nil)
}

