fn iteration(finished: bool, value: Option<Value>) -> Value {
    let mut m = HashMap::new();
    m.insert(key("finished"), Value::Bool(finished));
    if let Some(v) = value {
        m.insert(key("value"), v);
    }
    Value::dict(m)
}

fn std_iter(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    match &args[0] {
        Value::Str(s) => {
            let s = s.clone();
            let ix = RefCell::new(0usize);
            Ok(native("std.iter<impl>", move |interp, args, _, pos| {
                check_arity(interp, &args, 0, pos)?;
                let mut i = ix.borrow_mut();
                if *i < s.len() {
                    let v = Value::Byte(s[*i]);
                    *i += 1;
                    Ok(iteration(false, Some(v)))
                } else {
                    Ok(iteration(true, None))
                }
            }))
        }
        Value::Array(a) => {
            let a = a.clone();
            let ix = RefCell::new(0usize);
            Ok(native("std.iter<impl>", move |interp, args, _, pos| {
                check_arity(interp, &args, 0, pos)?;
                let mut i = ix.borrow_mut();
                let arr = a.borrow();
                if *i < arr.len() {
                    let v = arr[*i].clone();
                    *i += 1;
                    Ok(iteration(false, Some(v)))
                } else {
                    Ok(iteration(true, None))
                }
            }))
        }
        Value::Dict(d) => {
            let entries: Vec<(Value, Value)> = d.borrow().iter().map(|(k, v)| (k.clone(), v.clone())).collect();
            let ix = RefCell::new(0usize);
            Ok(native("std.iter<impl>", move |interp, args, _, pos| {
                check_arity(interp, &args, 0, pos)?;
                let mut i = ix.borrow_mut();
                if *i < entries.len() {
                    let (k, v) = entries[*i].clone();
                    *i += 1;
                    let mut m = HashMap::new();
                    m.insert(key("key"), k);
                    m.insert(key("value"), v);
                    Ok(iteration(false, Some(Value::dict(m))))
                } else {
                    Ok(iteration(true, None))
                }
            }))
        }
        other => Err(interp.type_error(pos, other, "string, array or dict")),
    }
}

fn std_range(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 3, pos)?;
    let any_float = args.iter().any(|v| matches!(v, Value::Float(_)));
    for v in &args {
        if !matches!(v, Value::Int(_) | Value::Float(_)) {
            return Err(interp.type_error(pos, v, "int or float"));
        }
    }
    if any_float {
        let to_f = |v: &Value| match v {
            Value::Int(i) => *i as f64,
            Value::Float(x) => *x,
            _ => 0.0,
        };
        let (from, to, step) = (to_f(&args[0]), to_f(&args[1]), to_f(&args[2]));
        let cur = RefCell::new(from);
        Ok(native("std.range<impl>", move |interp, args, _, pos| {
            check_arity(interp, &args, 0, pos)?;
            let mut c = cur.borrow_mut();
            let more = if step > 0.0 { *c < to } else if step < 0.0 { *c > to } else { false };
            if more {
                let v = *c;
                *c += step;
                Ok(iteration(false, Some(Value::Float(v))))
            } else {
                Ok(iteration(true, None))
            }
        }))
    } else {
        let to_i = |v: &Value| match v {
            Value::Int(i) => *i,
            _ => 0,
        };
        let (from, to, step) = (to_i(&args[0]), to_i(&args[1]), to_i(&args[2]));
        let cur = RefCell::new(from);
        Ok(native("std.range<impl>", move |interp, args, _, pos| {
            check_arity(interp, &args, 0, pos)?;
            let mut c = cur.borrow_mut();
            let more = if step > 0 { *c < to } else if step < 0 { *c > to } else { false };
            if more {
                let v = *c;
                *c = c.wrapping_add(step);
                Ok(iteration(false, Some(Value::Int(v))))
            } else {
                Ok(iteration(true, None))
            }
        }))
    }
}

// ------------------------------------------------------------------ errors

fn std_error(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 2, pos)?;
    let desc = interp.str_arg(&args[0], pos)?;
    Ok(Value::Error(Rc::new(super::value::ErrorValue { description: desc, context: args[1].clone() })))
}

fn std_panic(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    Err(interp.panic(pos, format!("std.panic({})", args[0].nested_string())))
}

fn std_catch(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    if !matches!(args[0], Value::Function(_)) {
        return Err(interp.type_error(pos, &args[0], "function"));
    }
    match interp.call(&args[0], Vec::new(), Value::Nil, pos) {
        Ok(v) => Ok(v),
        Err(Flow::Panic(p)) => Ok(Value::error(format!("caught panic: {}", p), key("panic"))),
        Err(other) => Err(other),
    }
}

fn has_error(v: &Value) -> bool {
    match v {
        Value::Error(_) => true,
        Value::Array(a) => a.borrow().iter().any(has_error),
        Value::Dict(d) => d.borrow().iter().any(|(k, v)| has_error(k) || has_error(v)),
        _ => false,
    }
}

fn std_has_error(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    Ok(Value::Bool(has_error(&args[0])))
}

fn std_assert(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    match &args[0] {
        Value::Bool(true) => Ok(Value::Nil),
        Value::Bool(false) => Err(interp.panic(pos, "assertion failed")),
        other => Err(interp.type_error(pos, other, "bool")),
    }
}

fn type_matches(v: &Value, t: &[u8]) -> Option<bool> {
    let name = match t {
        b"nil" => "nil",
        b"bool" => "bool",
        b"int" => "int",
        b"float" => "float",
        b"char" => "char",
        b"string" => "string",
        b"array" => "array",
        b"dict" => "dict",
        b"function" => "function",
        b"error" => "error",
        _ => return None,
    };
    Some(v.type_name() == name)
}

fn std_typecheck(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 2, pos)?;
    let t = interp.str_arg(&args[1], pos)?;
    match type_matches(&args[0], &t) {
        None => Err(interp.invalid_value(pos, &args[1], "valid type")),
        Some(true) => Ok(args[0].clone()),
        Some(false) => Err(interp.type_error(pos, &args[0], &String::from_utf8_lossy(&t))),
    }
}

fn std_try_typecheck(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 2, pos)?;
    let t = interp.str_arg(&args[1], pos)?;
    match type_matches(&args[0], &t) {
        None => Err(interp.invalid_value(pos, &args[1], "valid type")),
        Some(true) => Ok(Value::Nil),
        Some(false) => Ok(Value::error(
            format!(
                "type error: expected {}, got {} ({})",
                String::from_utf8_lossy(&t),
                args[0].type_name(),
                args[0].nested_string()
            ),
            args[0].clone(),
        )),
    }
}

// ------------------------------------------------------------------ conversions

fn std_to_string(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    Ok(Value::string(args[0].top_bytes()))
}

fn std_int(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    match &args[0] {
        Value::Int(i) => Ok(Value::Int(*i)),
        Value::Float(x) => Ok(Value::Int(*x as i64)),
        Value::Str(s) => match std::str::from_utf8(s).ok().and_then(|s| s.parse::<i64>().ok()) {
            Some(i) => Ok(Value::Int(i)),
            None => Err(interp.invalid_value(pos, &args[0], "valid integer")),
        },
        other => Err(interp.type_error(pos, other, "int, float or string")),
    }
}

fn std_float(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    match &args[0] {
        Value::Int(i) => Ok(Value::Float(*i as f64)),
        Value::Float(x) => Ok(Value::Float(*x)),
        Value::Str(s) => match std::str::from_utf8(s).ok().and_then(|s| s.parse::<f64>().ok()) {
            Some(x) => Ok(Value::Float(x)),
            None => Err(interp.invalid_value(pos, &args[0], "valid integer")),
        },
        other => Err(interp.type_error(pos, other, "int, float or string")),
    }
}

fn std_bytes(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    let s = interp.str_arg(&args[0], pos)?;
    Ok(Value::array(s.iter().map(|b| Value::Byte(*b)).collect()))
}

// ------------------------------------------------------------------ strings

fn std_substr(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 3, pos)?;
    let s = interp.str_arg(&args[0], pos)?;
    let start = interp.int_arg(&args[1], pos)?;
    let len = interp.int_arg(&args[2], pos)?;
    if start < 0 || len < 0 {
        return Ok(Value::Nil);
    }
    let (start, len) = (start as usize, len as usize);
    match start.checked_add(len) {
        Some(end) if end <= s.len() => Ok(Value::string(s[start..end].to_vec())),
        _ => Ok(Value::Nil),
    }
}

fn split_bytes(s: &[u8], pat: &[u8]) -> Vec<Vec<u8>> {
    if pat.is_empty() {
        // like Rust's str::split("") : empty, each char, empty
        let mut out = vec![Vec::new()];
        for b in s {
            out.push(vec![*b]);
        }
        out.push(Vec::new());
        return out;
    }
    let mut out = Vec::new();
    let mut start = 0;
    let mut i = 0;
    while i + pat.len() <= s.len() {
        if &s[i..i + pat.len()] == pat {
            out.push(s[start..i].to_vec());
            i += pat.len();
            start = i;
        } else {
            i += 1;
        }
    }
    out.push(s[start..].to_vec());
    out
}

fn std_split(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 2, pos)?;
    let s = interp.str_arg(&args[0], pos)?;
    let pat = interp.str_arg(&args[1], pos)?;
    Ok(Value::array(split_bytes(&s, &pat).into_iter().map(Value::string).collect()))
}

fn std_trim(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    let s = interp.str_arg(&args[0], pos)?;
    let start = s.iter().position(|b| !b.is_ascii_whitespace()).unwrap_or(s.len());
    let end = s.iter().rposition(|b| !b.is_ascii_whitespace()).map(|p| p + 1).unwrap_or(start);
    Ok(Value::string(s[start..end.max(start)].to_vec()))
}

fn std_replace(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 3, pos)?;
    let s = interp.str_arg(&args[0], pos)?;
    let pat = interp.str_arg(&args[1], pos)?;
    let rep = interp.str_arg(&args[2], pos)?;
    let parts = split_bytes(&s, &pat);
    let mut out = Vec::new();
    for (i, p) in parts.iter().enumerate() {
        if i > 0 {
            out.extend_from_slice(&rep);
        }
        out.extend_from_slice(p);
    }
    Ok(Value::string(out))
}

fn std_contains(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 2, pos)?;
    match &args[0] {
        Value::Str(s) => match &args[1] {
            Value::Byte(b) => Ok(Value::Bool(s.contains(b))),
            other => Err(interp.type_error(pos, other, "char")),
        },
        Value::Array(a) => Ok(Value::Bool(a.borrow().contains(&args[1]))),
        Value::Dict(d) => Ok(Value::Bool(d.borrow().contains_key(&args[1]))),
        other => Err(interp.type_error(pos, other, "string ,array or dict")),
    }
}

fn std_sort(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    match &args[0] {
        Value::Array(a) => {
            a.borrow_mut().sort_by(|x, y| x.compare(y));
            Ok(Value::Nil)
        }
        other => Err(interp.type_error(pos, other, "array")),
    }
}

fn std_bind(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 2, pos)?;
    let obj = args[0].clone();
    let func = args[1].clone();
    if !matches!(func, Value::Function(_)) {
        return Err(interp.type_error(pos, &func, "function"));
    }
    Ok(native("std.bind<impl>", move |interp, args, _, pos| interp.call(&func, args, obj.clone(), pos)))
}

// ------------------------------------------------------------------ environment

fn std_env(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    let name = interp.str_arg(&args[0], pos)?;
    use std::os::unix::ffi::OsStrExt;
    let os = std::ffi::OsStr::from_bytes(&name);
    if name.is_empty() || name.contains(&b'=') || name.contains(&0) {
        return Ok(Value::Nil);
    }
    match std::env::var_os(os) {
        Some(v) => Ok(Value::string(v.as_bytes().to_vec())),
        None => Ok(Value::Nil),
    }
}

fn std_export(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 2, pos)?;
    let name = interp.str_arg(&args[0], pos)?;
    let value = interp.str_arg(&args[1], pos)?;
    use std::os::unix::ffi::OsStrExt;
    if name.is_empty() || name.contains(&b'=') || name.contains(&0) || value.contains(&0) {
        return Ok(Value::Nil);
    }
    std::env::set_var(std::ffi::OsStr::from_bytes(&name), std::ffi::OsStr::from_bytes(&value));
    Ok(Value::Nil)
}

fn std_cwd(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 0, pos)?;
    use std::os::unix::ffi::OsStrExt;
    match std::env::current_dir() {
        Ok(p) => Ok(Value::string(p.as_os_str().as_bytes().to_vec())),
        Err(e) => Ok(Value::error(e.to_string(), Value::Nil)),
    }
}

fn std_cd(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    let dir = interp.str_arg(&args[0], pos)?;
    use std::os::unix::ffi::OsStrExt;
    match std::env::set_current_dir(std::ffi::OsStr::from_bytes(&dir)) {
        Ok(()) => Ok(Value::Nil),
        Err(e) => Ok(Value::error(e.to_string(), Value::Nil)),
    }
}

fn std_glob(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    let pat = interp.str_arg(&args[0], pos)?;
    let pat = String::from_utf8_lossy(&pat).to_string();
    use std::os::unix::ffi::OsStrExt;
    match glob::glob(&pat) {
        Ok(paths) => {
            let mut out = Vec::new();
            for p in paths {
                match p {
                    Ok(p) => out.push(Value::string(p.as_os_str().as_bytes().to_vec())),
                    Err(e) => return Ok(Value::error(e.to_string(), Value::Nil)),
                }
            }
            Ok(Value::array(out))
        }
        Err(e) => Ok(Value::error("Invalid pattern", key(e.msg))),
    }
}

fn std_read(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    if args.len() > 1 {
        return Err(interp.arity_error(pos, args.len(), 1));
    }
    if let Some(prompt) = args.first() {
        let p = interp.str_arg(prompt, pos)?;
        let stdout = std::io::stdout();
        let mut out = stdout.lock();
        let _ = out.write_all(&p);
        let _ = out.flush();
    }
    let mut line = Vec::new();
    let stdin = std::io::stdin();
    let mut lock = stdin.lock();
    use std::io::BufRead;
    match lock.read_until(b'\n', &mut line) {
        Ok(_) => Ok(Value::string(line)),
        Err(e) => Err(interp.panic(pos, e.to_string())),
    }
}

fn std_exit(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    let code = interp.int_arg(&args[0], pos)?;
    if !(0..=255).contains(&code) {
        return Err(interp.invalid_value(pos, &args[0], "valid exit code"));
    }
    Err(Flow::Exit(code as i32))
}

fn std_args(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 0, pos)?;
    let items = interp.args.iter().map(|a| Value::string(a.as_bytes().to_vec())).collect();
    Ok(Value::array(items))
}

fn std_sleep(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    let ms = interp.int_arg(&args[0], pos)?;
    if ms < 0 {
        return Err(interp.invalid_value(pos, &args[0], "positive integer"));
    }
    std::thread::sleep(std::time::Duration::from_millis(ms as u64));
    Ok(Value::Nil)
}

fn std_rand(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 0, pos)?;
    let x: f64 = interp.rng.gen();
    Ok(Value::Float(x))
}

fn std_randint(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 2, pos)?;
    let a = interp.int_arg(&args[0], pos)?;
    let b = interp.int_arg(&args[1], pos)?;
    if a > b {
        interp.flush_stdout();
        eprintln!(
            "\nthread 'main' panicked at /usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/rand-0.8.5/src/rng.rs:134:9:\ncannot sample empty range\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace"
        );
        std::process::exit(101);
    }
    let x: i64 = interp.rng.gen_range(a..=b);
    Ok(Value::Int(x))
}

fn std_randseed(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    let seed = interp.int_arg(&args[0], pos)?;
    interp.rng = rand_chacha::ChaCha8Rng::seed_from_u64(seed as u64);
    Ok(Value::Nil)
}

// ------------------------------------------------------------------ import

fn std_import(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    let p = interp.str_arg(&args[0], pos)?;
    use std::os::unix::ffi::OsStrExt;
    let rel = std::path::PathBuf::from(std::ffi::OsStr::from_bytes(&p));
    let current = interp.current_path();
    let base = std::path::Path::new(current.as_ref());
    let joined = if rel.is_absolute() {
        rel
    } else {
        match base.parent() {
            Some(dir) if current.as_ref() != "<stdin>" => dir.join(&rel),
            _ => rel,
        }
    };
    let canonical = match joined.canonicalize() {
        Ok(c) => c,
        Err(e) => return Err(interp.panic(pos, e.to_string())),
    };
    if let Some(v) = interp.modules.get(&canonical) {
        return Ok(v.clone());
    }
    let source = match std::fs::read(&canonical) {
        Ok(s) => s,
        Err(e) => return Err(interp.panic(pos, e.to_string())),
    };
    let path_str = canonical.to_string_lossy().to_string();
    let mut parser = crate::parser::Parser::new(&source);
    let ast = parser.parse_program();
    let syntax_errors = parser.errors;
    {
        let stderr = std::io::stderr();
        let mut err = stderr.lock();
        for e in syntax_errors.iter().take(20) {
            let _ = writeln!(err, "{}", e.display(&path_str));
        }
        if syntax_errors.len() > 20 {
            let _ = writeln!(err, "20 more supressed syntax errors");
        }
    }
    let analysis = crate::program::Analyzer::analyze(&ast);
    {
        let stderr = std::io::stderr();
        let mut err = stderr.lock();
        for e in &analysis.errors {
            let _ = writeln!(err, "{}", e.display(&path_str));
        }
    }
    if !syntax_errors.is_empty() || !analysis.errors.is_empty() || analysis.failed {
        return Err(interp.panic(pos, format!("failed to import module ({})", path_str)));
    }
    let saved_args = std::mem::take(&mut interp.args);
    let result = interp.run_program(&analysis.program, Rc::from(path_str.as_str()));
    interp.args = saved_args;
    let value = result?;
    interp.modules.insert(canonical, value.clone());
    Ok(value)
}

// ------------------------------------------------------------------ regex

fn std_regex(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    let pat = interp.str_arg(&args[0], pos)?;
    let pat = String::from_utf8_lossy(&pat).to_string();
    let re = match regex::bytes::Regex::new(&pat) {
        Ok(r) => Rc::new(r),
        Err(e) => return Ok(Value::error("invalid regex", key(&e.to_string()))),
    };
    let mut m = HashMap::new();
    {
        let re = re.clone();
        m.insert(
            key("match"),
            native("std.regex<match>", move |interp, args, _, pos| {
                check_arity(interp, &args, 1, pos)?;
                let s = interp.str_arg(&args[0], pos)?;
                Ok(Value::Bool(re.is_match(&s)))
            }),
        );
    }
    {
        let re = re.clone();
        m.insert(
            key("split"),
            native("std.regex<split>", move |interp, args, _, pos| {
                check_arity(interp, &args, 1, pos)?;
                let s = interp.str_arg(&args[0], pos)?;
                Ok(Value::array(re.split(&s).map(|p| Value::string(p.to_vec())).collect()))
            }),
        );
    }
    {
        let re = re.clone();
        m.insert(
            key("replace"),
            native("std.regex<replace>", move |interp, args, _, pos| {
                check_arity(interp, &args, 2, pos)?;
                let s = interp.str_arg(&args[0], pos)?;
                let rep = interp.str_arg(&args[1], pos)?;
                Ok(Value::string(re.replace_all(&s, rep.as_slice()).to_vec()))
            }),
        );
    }
    Ok(Value::dict(m))
}

// ------------------------------------------------------------------ json

fn json_encode_value(v: &Value, out: &mut Vec<u8>, indent: usize) -> bool {
    use std::fmt::Write as _;
    let mut s = String::new();
    match v {
        Value::Nil => s.push_str("null"),
        Value::Bool(b) => write!(s, "{}", b).unwrap(),
        Value::Int(i) => write!(s, "{}", i).unwrap(),
        Value::Float(x) => {
            if x.is_finite() {
                let mut buf = ryu_like(*x);
                s.push_str(&mut buf);
            } else {
                s.push_str("null");
            }
        }
        Value::Byte(b) => {
            let st = (*b as char).to_string();
            s.push_str(&serde_json::to_string(&st).unwrap());
        }
        Value::Str(bytes) => {
            let st = String::from_utf8_lossy(bytes);
            s.push_str(&serde_json::to_string(st.as_ref()).unwrap());
        }
        Value::Array(a) => {
            let a = a.borrow();
            if a.is_empty() {
                s.push_str("[]");
            } else {
                s.push_str("[\n");
                for (i, item) in a.iter().enumerate() {
                    if i > 0 {
                        s.push_str(",\n");
                    }
                    s.push_str(&"  ".repeat(indent + 1));
                    let mut sub = Vec::new();
                    if !json_encode_value(item, &mut sub, indent + 1) {
                        return false;
                    }
                    s.push_str(&String::from_utf8_lossy(&sub));
                }
                s.push('\n');
                s.push_str(&"  ".repeat(indent));
                s.push(']');
            }
        }
        Value::Dict(d) => {
            let d = d.borrow();
            if d.is_empty() {
                s.push_str("{}");
            } else {
                s.push_str("{\n");
                let mut first = true;
                for (k, item) in d.iter() {
                    let kstr = match k {
                        Value::Str(ks) => String::from_utf8_lossy(ks).to_string(),
                        _ => return false,
                    };
                    if !first {
                        s.push_str(",\n");
                    }
                    first = false;
                    s.push_str(&"  ".repeat(indent + 1));
                    s.push_str(&serde_json::to_string(&kstr).unwrap());
                    s.push_str(": ");
                    let mut sub = Vec::new();
                    if !json_encode_value(item, &mut sub, indent + 1) {
                        return false;
                    }
                    s.push_str(&String::from_utf8_lossy(&sub));
                }
                s.push('\n');
                s.push_str(&"  ".repeat(indent));
                s.push('}');
            }
        }
        Value::Function(_) | Value::Error(_) => return false,
    }
    out.extend_from_slice(s.as_bytes());
    true
}

fn ryu_like(x: f64) -> String {
    serde_json::to_string(&x).unwrap()
}

fn json_encode(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    let mut out = Vec::new();
    if json_encode_value(&args[0], &mut out, 0) {
        Ok(Value::string(out))
    } else {
        Err(interp.invalid_value(pos, &args[0], "nil, bool, byte, int, float, string, array or dict"))
    }
}

struct JsonValue(Value);

impl<'de> serde::Deserialize<'de> for JsonValue {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        struct V;
        impl<'de> serde::de::Visitor<'de> for V {
            type Value = JsonValue;
            fn expecting(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
                write!(f, "any valid JSON value")
            }
            fn visit_bool<E>(self, v: bool) -> Result<JsonValue, E> {
                Ok(JsonValue(Value::Bool(v)))
            }
            fn visit_i64<E>(self, v: i64) -> Result<JsonValue, E> {
                Ok(JsonValue(Value::Int(v)))
            }
            fn visit_u64<E: serde::de::Error>(self, v: u64) -> Result<JsonValue, E> {
                match i64::try_from(v) {
                    Ok(i) => Ok(JsonValue(Value::Int(i))),
                    Err(e) => Err(E::custom(e)),
                }
            }
            fn visit_f64<E>(self, v: f64) -> Result<JsonValue, E> {
                Ok(JsonValue(Value::Float(v)))
            }
            fn visit_str<E>(self, v: &str) -> Result<JsonValue, E> {
                Ok(JsonValue(Value::string(v.as_bytes().to_vec())))
            }
            fn visit_string<E>(self, v: String) -> Result<JsonValue, E> {
                Ok(JsonValue(Value::string(v.into_bytes())))
            }
            fn visit_none<E>(self) -> Result<JsonValue, E> {
                Ok(JsonValue(Value::Nil))
            }
            fn visit_unit<E>(self) -> Result<JsonValue, E> {
                Ok(JsonValue(Value::Nil))
            }
            fn visit_seq<A: serde::de::SeqAccess<'de>>(self, mut seq: A) -> Result<JsonValue, A::Error> {
                let mut out = Vec::new();
                while let Some(JsonValue(v)) = seq.next_element()? {
                    out.push(v);
                }
                Ok(JsonValue(Value::array(out)))
            }
            fn visit_map<A: serde::de::MapAccess<'de>>(self, mut map: A) -> Result<JsonValue, A::Error> {
                let mut out = HashMap::new();
                while let Some((k, JsonValue(v))) = map.next_entry::<String, JsonValue>()? {
                    out.insert(Value::string(k.into_bytes()), v);
                }
                Ok(JsonValue(Value::dict(out)))
            }
        }
        d.deserialize_any(V)
    }
}

fn json_decode(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    let s = interp.str_arg(&args[0], pos)?;
    match serde_json::from_slice::<JsonValue>(&s) {
        Ok(JsonValue(v)) => Ok(v),
        Err(e) => Ok(Value::error(e.to_string(), args[0].clone())),
    }
}

// ------------------------------------------------------------------ base64 / hex

const B64: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

fn b64_encode(data: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    for chunk in data.chunks(3) {
        let b = [chunk[0], *chunk.get(1).unwrap_or(&0), *chunk.get(2).unwrap_or(&0)];
        let n = ((b[0] as u32) << 16) | ((b[1] as u32) << 8) | b[2] as u32;
        out.push(B64[((n >> 18) & 63) as usize]);
        out.push(B64[((n >> 12) & 63) as usize]);
        if chunk.len() > 1 {
            out.push(B64[((n >> 6) & 63) as usize]);
        } else {
            out.push(b'=');
        }
        if chunk.len() > 2 {
            out.push(B64[(n & 63) as usize]);
        } else {
            out.push(b'=');
        }
    }
    out
}

/// Decoder mimicking the base64 crate 0.13 (STANDARD config) behaviour and messages.
fn b64_decode(input: &[u8]) -> Result<Vec<u8>, String> {
    fn val(c: u8) -> Option<u32> {
        match c {
            b'A'..=b'Z' => Some((c - b'A') as u32),
            b'a'..=b'z' => Some((c - b'a') as u32 + 26),
            b'0'..=b'9' => Some((c - b'0') as u32 + 52),
            b'+' => Some(62),
            b'/' => Some(63),
            _ => None,
        }
    }
    // strip trailing padding (at most 2), remember where padding starts
    let mut end = input.len();
    let mut pad = 0;
    while end > 0 && input[end - 1] == b'=' && pad < 2 {
        end -= 1;
        pad += 1;
    }
    let body = &input[..end];
    let mut out = Vec::new();
    let mut acc: u32 = 0;
    let mut bits = 0;
    for (i, &c) in body.iter().enumerate() {
        let v = match val(c) {
            Some(v) => v,
            None => return Err(format!("Invalid byte {}, offset {}.", c, i)),
        };
        acc = (acc << 6) | v;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push(((acc >> bits) & 0xFF) as u8);
        }
    }
    match body.len() % 4 {
        1 => return Err("Encoded text cannot have a 6-bit remainder.".to_string()),
        2 | 3 => {
            // check trailing bits are zero
            let mask = (1u32 << bits) - 1;
            if bits > 0 && (acc & mask) != 0 {
                let last = body[body.len() - 1];
                return Err(format!("Invalid last symbol {}, offset {}.", last, body.len() - 1));
            }
        }
        _ => {}
    }
    Ok(out)
}

fn base64_encode(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    let s = interp.str_arg(&args[0], pos)?;
    Ok(Value::string(b64_encode(&s)))
}

fn base64_decode(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    let s = interp.str_arg(&args[0], pos)?;
    match b64_decode(&s) {
        Ok(v) => Ok(Value::string(v)),
        Err(e) => Ok(Value::error(e, args[0].clone())),
    }
}

fn hex_encode(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    let s = interp.str_arg(&args[0], pos)?;
    Ok(Value::string(hex::encode(s.as_slice()).into_bytes()))
}

fn hex_decode(interp: &mut Interp, args: Args, _: Value, pos: Pos) -> EvalResult {
    check_arity(interp, &args, 1, pos)?;
    let s = interp.str_arg(&args[0], pos)?;
    match hex::decode(s.as_slice()) {
        Ok(v) => Ok(Value::string(v)),
        Err(e) => Ok(Value::error(e.to_string(), args[0].clone())),
    }
}

