use std::collections::HashMap;
use std::fs::File;
use std::io::{Read, Write};
use std::os::fd::{AsRawFd, FromRawFd, OwnedFd};
use std::os::unix::ffi::OsStrExt;
use std::process::{Command, Stdio};

use crate::pos::Pos;
use crate::program::*;

use super::interp::{EvalResult, Flow, Interp};
use super::value::Value;

// ------------------------------------------------------------------ expanded representation

#[derive(Clone, Debug)]
enum Piece {
    Lit(Vec<u8>),
    Star,
    Question,
}

#[derive(Clone, Debug)]
enum OutTarget {
    File { path: Vec<u8>, append: bool },
    Fd(u8),
}

#[derive(Clone, Debug)]
enum Redir {
    Output { fd: u8, target: OutTarget },
    InputFile(Vec<u8>),
    HereString(Vec<u8>),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Builtin {
    Cd,
    Exec,
    Alias,
}

#[derive(Clone, Debug)]
struct Prepared {
    program: Vec<u8>,
    args: Vec<Vec<u8>>,
    redirs: Vec<Redir>,
    abort_on_error: bool,
    pos: Pos,
    pos_str: String,
    builtin: Option<Builtin>,
}

/// Thread-safe error representation.
#[derive(Clone, Debug)]
enum CmdError {
    Single { description: String, status: i64, pos_str: String },
    Many { description: String, errors: Vec<CmdError> },
}

impl CmdError {
    fn description(&self) -> &str {
        match self {
            CmdError::Single { description, .. } | CmdError::Many { description, .. } => description,
        }
    }

    fn context_value(&self) -> Value {
        match self {
            CmdError::Single { status, pos_str, .. } => {
                let mut m = HashMap::new();
                m.insert(Value::string(b"status".to_vec()), Value::Int(*status));
                m.insert(Value::string(b"pos".to_vec()), Value::string(pos_str.as_bytes().to_vec()));
                Value::dict(m)
            }
            CmdError::Many { errors, .. } => Value::array(errors.iter().map(|e| e.to_value()).collect()),
        }
    }

    fn to_value(&self) -> Value {
        Value::error(self.description().to_string(), self.context_value())
    }
}

fn single_error(description: String, status: i64, pos_str: &str) -> CmdError {
    CmdError::Single { description, status, pos_str: pos_str.to_string() }
}

// ------------------------------------------------------------------ expansion

fn expand_value(interp: &Interp, v: &Value, pos: Pos) -> Result<Vec<Vec<u8>>, Flow> {
    match v {
        Value::Nil => Ok(vec![Vec::new()]),
        Value::Bool(_) | Value::Int(_) | Value::Float(_) | Value::Byte(_) | Value::Str(_) => Ok(vec![v.top_bytes()]),
        Value::Array(a) => {
            let a = a.borrow();
            let mut out = Vec::new();
            for item in a.iter() {
                match item {
                    Value::Nil => out.push(Vec::new()),
                    Value::Bool(_) | Value::Int(_) | Value::Float(_) | Value::Byte(_) | Value::Str(_) => {
                        out.push(item.top_bytes())
                    }
                    other => {
                        return Err(interp.type_error(pos, other, "nil, bool, int, float, byte or string"));
                    }
                }
            }
            Ok(out)
        }
        other => Err(interp.type_error(pos, other, "nil, bool, int, float, byte or string")),
    }
}

fn home_dir() -> Vec<u8> {
    match std::env::var_os("HOME") {
        Some(h) => h.as_bytes().to_vec(),
        None => Vec::new(),
    }
}

/// Expand an argument into zero or more strings.
fn expand_argument(interp: &mut Interp, arg: &PArgument) -> Result<Vec<Vec<u8>>, Flow> {
    // each part yields a list of alternative piece-sequences
    let mut acc: Option<Vec<Vec<Piece>>> = None;
    let mut has_glob = false;
    for part in &arg.parts {
        let alternatives: Vec<Vec<Piece>> = match part {
            PArgPart::Literal(s) => vec![vec![Piece::Lit(s.clone())]],
            PArgPart::Slot(slot, pos) => {
                let v = interp.frames.last().unwrap().slots[*slot].borrow().clone();
                expand_value(interp, &v, *pos)?.into_iter().map(|s| vec![Piece::Lit(s)]).collect()
            }
            PArgPart::Star => {
                has_glob = true;
                vec![vec![Piece::Star]]
            }
            PArgPart::Percent => {
                has_glob = true;
                vec![vec![Piece::Question]]
            }
            PArgPart::Home => {
                let mut h = home_dir();
                h.push(b'/');
                vec![vec![Piece::Lit(h)]]
            }
        };
        if alternatives.is_empty() {
            continue;
        }
        acc = Some(match acc {
            None => alternatives,
            Some(prev) => {
                let mut out = Vec::new();
                for alt in &alternatives {
                    for p in &prev {
                        let mut seq = p.clone();
                        seq.extend(alt.iter().cloned());
                        out.push(seq);
                    }
                }
                out
            }
        });
    }
    let seqs = match acc {
        None => return Ok(Vec::new()),
        Some(s) => s,
    };
    let mut result = Vec::new();
    for seq in seqs {
        if has_glob && seq.iter().any(|p| !matches!(p, Piece::Lit(_))) {
            let mut pattern = String::new();
            for p in &seq {
                match p {
                    Piece::Lit(s) => pattern.push_str(&glob::Pattern::escape(&String::from_utf8_lossy(s))),
                    Piece::Star => pattern.push('*'),
                    Piece::Question => pattern.push('?'),
                }
            }
            if let Ok(paths) = glob::glob(&pattern) {
                for p in paths.flatten() {
                    let mut bytes = Vec::new();
                    if !p.is_absolute() {
                        bytes.extend_from_slice(b"./");
                    }
                    bytes.extend_from_slice(p.as_os_str().as_bytes());
                    result.push(bytes);
                }
            }
        } else {
            let mut s = Vec::new();
            for p in &seq {
                if let Piece::Lit(l) = p {
                    s.extend_from_slice(l);
                }
            }
            result.push(s);
        }
    }
    Ok(result)
}

fn expand_single(interp: &mut Interp, arg: &PArgument, what: &str, pos: Pos) -> Result<Vec<u8>, Flow> {
    let mut items = expand_argument(interp, arg)?;
    if items.len() != 1 {
        return Err(interp.panic(pos, format!("{} expansion resulted in {} items", what, items.len())));
    }
    Ok(items.pop().unwrap())
}

fn literal_program(arg: &PArgument) -> Option<&[u8]> {
    match &arg.parts[..] {
        [PArgPart::Literal(s)] => Some(s),
        _ => None,
    }
}

pub fn builtin_name(arg: &crate::ast::Argument) -> bool {
    match &arg.parts[..] {
        [crate::ast::ArgPart::Literal(s)] => matches!(s.as_slice(), b"cd" | b"exec" | b"alias"),
        _ => false,
    }
}

fn prepare_basic(interp: &mut Interp, cmd: &PBasicCommand) -> Result<Prepared, Flow> {
    let (program, args, redirections, abort_on_error, pos) = match cmd {
        PBasicCommand::Command { program, args, redirections, abort_on_error, pos } => {
            (program, args, redirections, *abort_on_error, *pos)
        }
        PBasicCommand::IllFormed => {
            return Err(interp.panic(Pos::default(), "ill-formed command"));
        }
    };
    let builtin = match literal_program(program) {
        Some(b"cd") => Some(Builtin::Cd),
        Some(b"exec") => Some(Builtin::Exec),
        Some(b"alias") => Some(Builtin::Alias),
        _ => None,
    };
    let prog = if builtin.is_some() {
        literal_program(program).unwrap().to_vec()
    } else {
        expand_single(interp, program, "program", pos)?
    };
    let mut argv = Vec::new();
    for a in args {
        argv.extend(expand_argument(interp, a)?);
    }
    let mut redirs = Vec::new();
    for r in redirections {
        match r {
            PRedirection::Output { source, target } | PRedirection::Append { source, target } => {
                let append = matches!(r, PRedirection::Append { .. });
                let fd = *source as u8;
                let t = match target {
                    PRedirectionTarget::Fd(n) => OutTarget::Fd(*n as u8),
                    PRedirectionTarget::File(arg) => {
                        let path = expand_single(interp, arg, "redirection", arg.pos)?;
                        OutTarget::File { path, append }
                    }
                };
                redirs.push(Redir::Output { fd, target: t });
            }
            PRedirection::Input { literal, source } => {
                let s = expand_single(interp, source, "redirection", source.pos)?;
                if *literal {
                    let mut s = s;
                    s.push(b'\n');
                    redirs.push(Redir::HereString(s));
                } else {
                    redirs.push(Redir::InputFile(s));
                }
            }
            PRedirection::IllFormed => {}
        }
    }
    let pos_str = format!("{} ({})", interp.current_path(), pos);
    Ok(Prepared { program: prog, args: argv, redirs, abort_on_error, pos, pos_str, builtin })
}

// ------------------------------------------------------------------ execution

enum Target {
    Inherit(i32),
    Owned(OwnedFd),
}

impl Target {
    fn dup(&self) -> std::io::Result<Target> {
        match self {
            Target::Inherit(fd) => {
                let n = unsafe { libc::dup(*fd) };
                if n < 0 {
                    return Err(std::io::Error::last_os_error());
                }
                Ok(Target::Owned(unsafe { OwnedFd::from_raw_fd(n) }))
            }
            Target::Owned(fd) => Ok(Target::Owned(fd.try_clone()?)),
        }
    }

    fn into_stdio(self) -> Stdio {
        match self {
            Target::Inherit(_) => Stdio::inherit(),
            Target::Owned(fd) => Stdio::from(fd),
        }
    }
}

fn make_pipe() -> std::io::Result<(OwnedFd, OwnedFd)> {
    let mut fds = [0i32; 2];
    if unsafe { libc::pipe(fds.as_mut_ptr()) } < 0 {
        return Err(std::io::Error::last_os_error());
    }
    Ok(unsafe { (OwnedFd::from_raw_fd(fds[0]), OwnedFd::from_raw_fd(fds[1])) })
}

struct CaptureSink {
    stdout_w: OwnedFd,
    stderr_w: OwnedFd,
}

enum StdinSource {
    Inherit,
    Fd(OwnedFd),
    Here(Vec<u8>),
}

/// Spawn and wait a pipeline. Returns Ok(()) or the error (and whether the block must abort).
fn run_pipeline(cmds: &[Prepared], capture: Option<&CaptureSink>) -> Result<(), (CmdError, bool)> {
    let n = cmds.len();
    let mut children: Vec<(std::process::Child, usize)> = Vec::new();
    let mut prev_read: Option<OwnedFd> = None;
    let mut writer_threads = Vec::new();

    for (i, cmd) in cmds.iter().enumerate() {
        // base targets
        let mut stdin: StdinSource = match prev_read.take() {
            Some(fd) => StdinSource::Fd(fd),
            None => StdinSource::Inherit,
        };
        let mut next_read: Option<OwnedFd> = None;
        let mut stdout: Target = if i + 1 < n {
            let (r, w) = make_pipe().map_err(|e| (single_error(e.to_string(), 127, &cmd.pos_str), true))?;
            next_read = Some(r);
            Target::Owned(w)
        } else {
            match capture {
                Some(sink) => Target::Owned(
                    sink.stdout_w.try_clone().map_err(|e| (single_error(e.to_string(), 127, &cmd.pos_str), true))?,
                ),
                None => Target::Inherit(1),
            }
        };
        let mut stderr: Target = match capture {
            Some(sink) => Target::Owned(
                sink.stderr_w.try_clone().map_err(|e| (single_error(e.to_string(), 127, &cmd.pos_str), true))?,
            ),
            None => Target::Inherit(2),
        };
        // redirections, in order
        for r in &cmd.redirs {
            match r {
                Redir::Output { fd, target } => {
                    if *fd != 1 && *fd != 2 {
                        unreachable!();
                    }
                    let new_target = match target {
                        OutTarget::File { path, append } => {
                            let p = std::path::Path::new(std::ffi::OsStr::from_bytes(path));
                            let file = if *append {
                                std::fs::OpenOptions::new().create(true).append(true).open(p)
                            } else {
                                std::fs::OpenOptions::new().create(true).write(true).truncate(true).open(p)
                            };
                            match file {
                                Ok(f) => Target::Owned(OwnedFd::from(f)),
                                Err(e) => return Err((single_error(e.to_string(), 127, &cmd.pos_str), true)),
                            }
                        }
                        OutTarget::Fd(n) => {
                            let src = if *n == 1 { &stdout } else { &stderr };
                            match src.dup() {
                                Ok(t) => t,
                                Err(e) => return Err((single_error(e.to_string(), 127, &cmd.pos_str), true)),
                            }
                        }
                    };
                    if *fd == 1 {
                        stdout = new_target;
                    } else {
                        stderr = new_target;
                    }
                }
                Redir::InputFile(path) => {
                    let p = std::path::Path::new(std::ffi::OsStr::from_bytes(path));
                    match File::open(p) {
                        Ok(f) => stdin = StdinSource::Fd(OwnedFd::from(f)),
                        Err(e) => return Err((single_error(e.to_string(), 127, &cmd.pos_str), true)),
                    }
                }
                Redir::HereString(s) => stdin = StdinSource::Here(s.clone()),
            }
        }
        let stdin_stdio = match stdin {
            StdinSource::Inherit => Stdio::inherit(),
            StdinSource::Fd(fd) => Stdio::from(fd),
            StdinSource::Here(data) => {
                let (r, w) = make_pipe().map_err(|e| (single_error(e.to_string(), 127, &cmd.pos_str), true))?;
                let mut wf = File::from(w);
                writer_threads.push(std::thread::spawn(move || {
                    let _ = wf.write_all(&data);
                }));
                Stdio::from(r)
            }
        };
        let mut command = Command::new(std::ffi::OsStr::from_bytes(&cmd.program));
        for a in &cmd.args {
            command.arg(std::ffi::OsStr::from_bytes(a));
        }
        command.stdin(stdin_stdio).stdout(stdout.into_stdio()).stderr(stderr.into_stdio());
        match command.spawn() {
            Ok(child) => children.push((child, i)),
            Err(e) => {
                drop(command);
                return Err((single_error(e.to_string(), 127, &cmd.pos_str), true));
            }
        }
        drop(command);
        prev_read = next_read;
    }
    drop(prev_read);

    let mut errors = Vec::new();
    let mut abort = false;
    for (mut child, i) in children {
        let status = child.wait();
        match status {
            Ok(st) => {
                if !st.success() {
                    use std::os::unix::process::ExitStatusExt;
                    let code = match st.code() {
                        Some(c) => c as i64,
                        None => 255 + st.signal().unwrap_or(0) as i64,
                    };
                    errors.push(single_error("command returned non-zero".to_string(), code, &cmds[i].pos_str));
                    if cmds[i].abort_on_error {
                        abort = true;
                    }
                }
            }
            Err(e) => {
                errors.push(single_error(e.to_string(), 127, &cmds[i].pos_str));
                abort = true;
            }
        }
    }
    for t in writer_threads {
        let _ = t.join();
    }
    match errors.len() {
        0 => Ok(()),
        1 => Err((errors.pop().unwrap(), abort)),
        _ => Err((CmdError::Many { description: "Some commands failed in the pipeline".to_string(), errors }, abort)),
    }
}

/// Run a sequence of pipelines (already prepared). Builtins are handled by the caller.
fn run_pipelines(pipelines: &[Vec<Prepared>], capture: Option<&CaptureSink>) -> Result<(), CmdError> {
    let mut errors: Vec<CmdError> = Vec::new();
    for p in pipelines {
        match run_pipeline(p, capture) {
            Ok(()) => {}
            Err((e, abort)) => {
                errors.push(e);
                if abort {
                    break;
                }
            }
        }
    }
    finish_errors(errors)
}

fn finish_errors(mut errors: Vec<CmdError>) -> Result<(), CmdError> {
    match errors.len() {
        0 => Ok(()),
        1 => Err(errors.pop().unwrap()),
        _ => Err(CmdError::Many { description: "Some commands failed in the block".to_string(), errors }),
    }
}

fn run_builtin(interp: &mut Interp, cmd: &Prepared) -> Result<(), CmdError> {
    match cmd.builtin.unwrap() {
        Builtin::Cd => {
            if cmd.args.len() != 1 {
                // reported as panic by the caller
                unreachable!();
            }
            let p = std::path::Path::new(std::ffi::OsStr::from_bytes(&cmd.args[0]));
            match std::env::set_current_dir(p) {
                Ok(()) => Ok(()),
                Err(e) => Err(single_error(e.to_string(), 127, &cmd.pos_str)),
            }
        }
        Builtin::Exec => {
            use std::os::unix::process::CommandExt;
            interp.flush_stdout();
            let mut command = Command::new(std::ffi::OsStr::from_bytes(&cmd.args[0]));
            for a in &cmd.args[1..] {
                command.arg(std::ffi::OsStr::from_bytes(a));
            }
            let e = command.exec();
            Err(single_error(e.to_string(), 127, &cmd.pos_str))
        }
        Builtin::Alias => {
            interp.flush_stdout();
            eprintln!(
                "\nthread 'main' panicked at src/runtime/command/exec/mod.rs:171:28:\nnot yet implemented\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace"
            );
            std::process::exit(101);
        }
    }
}

fn result_to_value(r: Result<(), CmdError>) -> Value {
    match r {
        Ok(()) => Value::Nil,
        Err(e) => e.to_value(),
    }
}

fn capture_result_to_value(r: Result<(), CmdError>, stdout: Vec<u8>, stderr: Vec<u8>) -> Value {
    let mut m = HashMap::new();
    m.insert(Value::string(b"stdout".to_vec()), Value::string(stdout));
    m.insert(Value::string(b"stderr".to_vec()), Value::string(stderr));
    match r {
        Ok(()) => Value::dict(m),
        Err(e) => {
            m.insert(Value::string(b"error".to_vec()), e.context_value());
            Value::error(e.description().to_string(), Value::dict(m))
        }
    }
}

fn run_captured(pipelines: &[Vec<Prepared>]) -> std::io::Result<(Result<(), CmdError>, Vec<u8>, Vec<u8>)> {
    let (out_r, out_w) = make_pipe()?;
    let (err_r, err_w) = make_pipe()?;
    let out_thread = std::thread::spawn(move || {
        let mut f = File::from(out_r);
        let mut buf = Vec::new();
        let _ = f.read_to_end(&mut buf);
        buf
    });
    let err_thread = std::thread::spawn(move || {
        let mut f = File::from(err_r);
        let mut buf = Vec::new();
        let _ = f.read_to_end(&mut buf);
        buf
    });
    let sink = CaptureSink { stdout_w: out_w, stderr_w: err_w };
    let result = run_pipelines(pipelines, Some(&sink));
    drop(sink);
    let stdout = out_thread.join().unwrap_or_default();
    let stderr = err_thread.join().unwrap_or_default();
    Ok((result, stdout, stderr))
}

pub fn run_block(interp: &mut Interp, kind: CommandBlockKind, commands: &[PCommand], pos: Pos) -> EvalResult {
    // expand everything first
    let mut pipelines: Vec<Vec<Prepared>> = Vec::new();
    for c in commands {
        match c {
            PCommand::Pipeline(basics) => {
                let mut v = Vec::new();
                for b in basics {
                    v.push(prepare_basic(interp, b)?);
                }
                pipelines.push(v);
            }
            PCommand::IllFormed => {}
        }
    }
    let _ = pos;
    match kind {
        CommandBlockKind::Synchronous => {
            let mut errors: Vec<CmdError> = Vec::new();
            for p in &pipelines {
                if p.len() == 1 && p[0].builtin.is_some() {
                    let cmd = &p[0];
                    if cmd.builtin == Some(Builtin::Cd) && cmd.args.len() != 1 {
                        return Err(interp.panic(
                            cmd.pos,
                            format!("argument expansion resulted in {} items", cmd.args.len()),
                        ));
                    }
                    if cmd.builtin == Some(Builtin::Exec) && cmd.args.is_empty() {
                        return Err(interp.panic(cmd.pos, "argument expansion resulted in 0 items"));
                    }
                    match run_builtin(interp, cmd) {
                        Ok(()) => {}
                        Err(e) => {
                            errors.push(e);
                            break;
                        }
                    }
                    continue;
                }
                match run_pipeline(p, None) {
                    Ok(()) => {}
                    Err((e, abort)) => {
                        errors.push(e);
                        if abort {
                            break;
                        }
                    }
                }
            }
            Ok(result_to_value(finish_errors(errors)))
        }
        CommandBlockKind::Capture => match run_captured(&pipelines) {
            Ok((r, out, err)) => Ok(capture_result_to_value(r, out, err)),
            Err(e) => Err(interp.panic(pos, e.to_string())),
        },
        CommandBlockKind::Asynchronous => {
            let handle = std::thread::spawn(move || run_pipelines(&pipelines, None));
            let cell = std::rc::Rc::new(std::cell::RefCell::new(Some(handle)));
            let join = super::value::Function::Native {
                name: "<command>.join".to_string(),
                func: std::rc::Rc::new(move |interp: &mut Interp, args: Vec<Value>, _self: Value, pos: Pos| {
                    if !args.is_empty() {
                        return Err(interp.arity_error(pos, args.len(), 0));
                    }
                    let h = cell.borrow_mut().take();
                    match h {
                        Some(h) => match h.join() {
                            Ok(r) => Ok(result_to_value(r)),
                            Err(_) => Err(interp.panic(pos, "async command panicked")),
                        },
                        None => Err(interp.panic(pos, "attempt to call join more than once")),
                    }
                }),
            };
            let mut m = HashMap::new();
            m.insert(Value::string(b"join".to_vec()), Value::Function(std::rc::Rc::new(join)));
            Ok(Value::dict(m))
        }
    }
}

