new = r'''/// Jaro-Winkler similarity, as used by clap for suggestions.
fn jaro_winkler(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.is_empty() && b.is_empty() {
        return 1.0;
    }
    if a.is_empty() || b.is_empty() {
        return 0.0;
    }
    let search_range = (a.len().max(b.len()) / 2).saturating_sub(1);
    let mut b_consumed = vec![false; b.len()];
    let mut matches = 0.0;
    let mut transpositions = 0.0;
    let mut b_match_index = 0;
    for (i, &ca) in a.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = (b.len() - 1).min(i + search_range);
        if min_bound > max_bound {
            continue;
        }
        for (j, &cb) in b.iter().enumerate() {
            if min_bound <= j && j <= max_bound && ca == cb && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    let jaro = if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0) * ((matches / a.len() as f64) + (matches / b.len() as f64) + ((matches - transpositions) / matches))
    };
    let prefix_len = a.iter().zip(b.iter()).take(4).take_while(|(x, y)| x == y).count() as f64;
    let jw = jaro + 0.1 * prefix_len * (1.0 - jaro);
    if jw > 1.0 { 1.0 } else { jw }
}

fn unexpected_argument(arg: &str) -> ! {
    let candidates = ["ast", "check", "lex", "program", "help", "version"];
    let mut suggestion: Option<(&str, f64)> = None;
    if let Some(name) = arg.strip_prefix("--") {
        for c in candidates {
            let score = jaro_winkler(name, c);
            if score > 0.8 && suggestion.map_or(true, |(_, s)| score > s) {
                suggestion = Some((c, score));
            }
        }
    }
    let mut msg = format!(
        "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n",
        arg
    );
    match suggestion {
        Some((c, _)) => {
            msg.push_str(&format!(
                "\tDid you mean \x1b[32m--\x1b[0m\x1b[32m{}\x1b[0m?\n\nUSAGE:\n    {} --{}\n",
                c,
                program_name(),
                c
            ));
        }
        None => {
            msg.push_str(&format!("\n{}\n", usage_line()));
        }
    }
    msg.push_str("\nFor more information try --help");
    eprintln!("{}", msg);
    std::process::exit(1);
}

fn parse_options() -> Options {
    let mut opts = Options { lex: false, ast: false, program: false, check: false, args: Vec::new() };
    let argv: Vec<String> = std::env::args().skip(1).collect();
    let mut i = 0;
    let mut positional_started = false;
    while i < argv.len() {
        let a = &argv[i];
        if !positional_started {
            if a == "--" {
                positional_started = true;
                i += 1;
                continue;
            }
            if let Some(long) = a.strip_prefix("--") {
                let name = long.split('=').next().unwrap_or("");
                let flag: Option<&mut bool> = match name {
                    "lex" => Some(&mut opts.lex),
                    "ast" => Some(&mut opts.ast),
                    "program" => Some(&mut opts.program),
                    "check" => Some(&mut opts.check),
                    "help" => {
                        print_help();
                        std::process::exit(0);
                    }
                    "version" => {
                        println!("Hush {}", VERSION);
                        std::process::exit(0);
                    }
                    _ => None,
                };
                match flag {
                    Some(f) => {
                        if *f {
                            eprintln!(
                                "error: The argument '--{}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {} --{}\n\nFor more information try --help",
                                name,
                                program_name(),
                                name
                            );
                            std::process::exit(1);
                        }
                        *f = true;
                    }
                    None => unexpected_argument(a),
                }
                i += 1;
                continue;
            }
            if a.len() > 1 && a.starts_with('-') {
                let first = a.chars().nth(1).unwrap();
                match first {
                    'h' => {
                        print_help();
                        std::process::exit(0);
                    }
                    'V' => {
                        println!("Hush {}", VERSION);
                        std::process::exit(0);
                    }
                    other => unexpected_argument(&format!("-{}", other)),
                }
            }
            positional_started = true;
