fn jaro_winkler(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.is_empty() && b.is_empty() {
        return 1.0;
    }
    if a.is_empty() || b.is_empty() {
        return 0.0;
    }
    let search_range = (a.len().max(b.len()) / 2).saturating_sub(1);
    let mut b_consumed = vec![false; b.len()];
    let mut matches = 0.0;
    let mut transpositions = 0.0;
    let mut b_match_index = 0;
    for (i, &ca) in a.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = (b.len() - 1).min(i + search_range);
        if min_bound > max_bound {
            continue;
        }
        for (j, &cb) in b.iter().enumerate() {
            if min_bound <= j && j <= max_bound && ca == cb && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    let jaro = if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0) * ((matches / a.len() as f64) + (matches / b.len() as f64) + ((matches - transpositions) / matches))
    };
    let prefix_len = a.iter().zip(b.iter()).take(4).take_while(|(x, y)| x == y).count() as f64;
    let jw = jaro + 0.1 * prefix_len * (1.0 - jaro);
    if jw > 1.0 { 1.0 } else { jw }
}

fn unexpected_argument(arg: &str) -> ! {
    let candidates = ["ast", "check", "lex", "program", "help", "version"];
    let mut suggestion: Option<(&str, f64)> = None;
    if let Some(name) = arg.strip_prefix("--") {
        for c in candidates {
            let score = jaro_winkler(name, c);
            if score > 0.8 && suggestion.map_or(true, |(_, s)| score > s) {
                suggestion = Some((c, score));
            }
        }
    }
    let mut msg = format!(
        "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n",
        arg
    );
