            msg.push_str(&format!(
                "\tDid you mean \x1b[32m--\x1b[0m\x1b[32m{}\x1b[0m?\n\nUSAGE:\n    {} --{}\n",
                c,
                program_name(),
                c
            ));
        }
        None => {
            msg.push_str(&format!("\n{}\n", usage_line()));
        }
    }
    msg.push_str("\nFor more information try --help");
    eprintln!("{}", msg);
    std::process::exit(1);
}

fn parse_options() -> Options {
    let mut opts = Options { lex: false, ast: false, program: false, check: false, args: Vec::new() };
    let argv: Vec<String> = std::env::args().skip(1).collect();
    let mut i = 0;
    let mut positional_started = false;
    while i < argv.len() {
        let a = &argv[i];
        if !positional_started {
            if a == "--" {
                positional_started = true;
                i += 1;
                continue;
            }
            if let Some(long) = a.strip_prefix("--") {
                let name = long.split('=').next().unwrap_or("");
                let flag: Option<&mut bool> = match name {
                    "lex" => Some(&mut opts.lex),
                    "ast" => Some(&mut opts.ast),
                    "program" => Some(&mut opts.program),
                    "check" => Some(&mut opts.check),
                    "help" => {
                        print_help();
                        std::process::exit(0);
                    }
                    "version" => {
                        println!("Hush {}", VERSION);
                        std::process::exit(0);
                    }
                    _ => None,
                };
                match flag {
                    Some(f) => {
                        if *f {
                            eprintln!(
                                "error: The argument '--{}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {} --{}\n\nFor more information try --help",
                                name,
                                program_name(),
                                name
                            );
                            std::process::exit(1);
                        }
                        *f = true;
                    }
                    None => unexpected_argument(a),
                }
                i += 1;
                continue;
            }
            if a.len() > 1 && a.starts_with('-') {
                let first = a.chars().nth(1).unwrap();
                match first {
                    'h' => {
                        print_help();
                        std::process::exit(0);
                    }
                    'V' => {
                        println!("Hush {}", VERSION);
                        std::process::exit(0);
                    }
                    other => unexpected_argument(&format!("-{}", other)),
                }
            }
            positional_started = true;
        }
        opts.args.push(a.clone());
        i += 1;
    }
    opts
}

